#!/usr/bin/env python3
"""Backstage · txtme.social: der Server-Teil des Kontrollpanels (Werkzeug «Website pflegen», Le Bureau nach Master 4.2).

  python3 _backstage/backstage.py [3213]      → http://127.0.0.1:3213/backstage/

  /backstage/            die Oberfläche (backstage/index.html, backstage.js, bureau.js)
  /backstage/pruefung.html  die Prüfung, läuft auch ohne das Werkzeug
  /backstage/api/<weg>   Daten und Aktionen (GET lesen, POST schreiben, JSON)
  /                      die Website: veröffentlichter Stand (inhalt/live/) über der gebauten Seite (out/), sonst out/ unverändert
  /entwurf/<seite>/      die Seite mit dem Entwurf (frisch gesetzt, nichts gebaut), /vorher/<seite>/ die veröffentlichte, beide mit Vorschau-Skript

Daten in inhalt/ (BACKSTAGE_DATEN für Wegwerf-Daten): stand.json (veröffentlicht), entwurf.json (in Arbeit), schritte/ (jedes Speichern, 80 für «Rückgängig»),
verlauf/ (jede Veröffentlichung samt den Seiten davor, 40), live/ (die veröffentlichten Seiten), _bau/ (Probe-Bau), bilder.json (hochgeladene Fotos),
zugang.json (Benutzer und Rollen), protokoll.log (wer wann was), fehler.log. Uploads unter public/media/u/.
Produkte, Preise und Kategorien pflegt das Medusa-Panel des txtme-Teams: Backstage zeigt den Katalog nur, ändert ihn nicht (MEDUSA).
Kein Hochladen, keine KI (ki=0), keine Schlüssel, keine Zählung."""
import base64
import datetime
import hashlib
import io
import json
import mimetypes
import os
import re
import shutil
import sys
import threading
import time
import traceback
from http import cookies
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, unquote, urlsplit

HIER = os.path.dirname(os.path.abspath(__file__))
ROOT = os.path.dirname(HIER)
sys.path.insert(0, HIER)
import inhalt as I  # noqa: E402
import sprache as S  # noqa: E402
from wache import Abgewiesen, Wache  # noqa: E402

VERSION = '2026-11-06.1'
NAME = 'txtme.social'   # Platzhalter-Name des Hauses (Robert wählt die Namen später): eine Stelle
WERKZEUG = 'Backstage'
PORT = int(sys.argv[1]) if len(sys.argv) > 1 and sys.argv[1].isdigit() else 3213
DATEN = os.path.abspath(os.environ.get('BACKSTAGE_DATEN') or os.path.join(ROOT, 'inhalt'))
OUT = I.OUT
UPLOADS = os.path.abspath(os.environ.get('BACKSTAGE_UPLOADS') or os.path.join(ROOT, 'public', 'media', 'u'))
OBERFLAECHE = os.path.join(ROOT, 'backstage')
KI = int(os.environ.get('BACKSTAGE_KI') or 0)   # bleibt 0: kein Modell, kein Schlüssel

F_STAND, F_ENTWURF, F_BILDER, F_PROT, F_FEHLER, F_BSP = (os.path.join(DATEN, n) for n in ('stand.json', 'entwurf.json', 'bilder.json', 'protokoll.log', 'fehler.log', 'beispiele.json'))
SCHRITTE, VERLAUF, LIVE, BAU = (os.path.join(DATEN, n) for n in ('schritte', 'verlauf', 'live', '_bau'))
SCHLOSS = threading.RLock()
LAUF = {'laeuft': False, 'schritt': '', 'schritte': [], 'fertig': None, 'fehler': '', 'start': 0, 'name': NAME, 'um': 0}

TEILE = ['produkte', 'neu_produkte', 'reihenfolge', 'kategorien', 'farben', 'angaben', 'versand', 'zahlarten', 'fragen', 'presse', 'recht', 'seo', 'hinweis', 'band', 'texte', 'aus', 'bilder', 'alt', 'woerter']
MEDUSA = {'produkte', 'neu_produkte', 'reihenfolge', 'kategorien', 'farben'}
DICT_TEILE = {'bilder', 'alt', 'seo', 'kategorien', 'farben', 'reihenfolge', 'angaben', 'versand', 'hinweis', 'band', 'woerter', 'aus'}
TEILNAME = {'produkte': 'Produkte', 'neu_produkte': 'Neue Produkte', 'reihenfolge': 'Reihenfolge', 'kategorien': 'Kategorien', 'farben': 'Farben', 'angaben': 'Angaben', 'versand': 'Versand',
            'zahlarten': 'Zahlarten', 'fragen': 'Fragen', 'presse': 'Presse', 'recht': 'Rechtliches', 'seo': 'Google & Teilen', 'hinweis': 'Hinweis', 'band': 'Hinweis-Leiste', 'texte': 'Texte',
            'bilder': 'Bilder', 'alt': 'Bildbeschreibungen', 'woerter': 'Sprachen', 'aus': 'Ausgeblendet'}
SPRACHEN = ('de',)
TEXT_MAX = 5000


class Fehler(ValueError):
    """Erwartete Meldung mit Stichwort fürs Lexikon der Prüfung («STICHWORT · Text», lex = Eintrag in pruefung.js)."""

    def __init__(self, text, lex='anfrage', status=400):
        super().__init__(text)
        self.lex, self.status = lex, status


# ------------------------------------------------------------------ Dateien, Protokoll
def jetzt():
    return datetime.datetime.now().astimezone().isoformat(timespec='seconds')


def protokoll(wer, rolle, text, datei=None):
    try:
        os.makedirs(DATEN, exist_ok=True)
        p = datei or F_PROT
        if os.path.exists(p) and os.path.getsize(p) > 400 * 1024:
            rest = open(p, encoding='utf-8', errors='replace').read()[-200 * 1024:]
            open(p, 'w', encoding='utf-8').write(rest[rest.find('\n') + 1:])
        with open(p, 'a', encoding='utf-8') as f:
            f.write(f'{jetzt()}  {wer or "-"}({rolle or "-"})  {re.sub(chr(10), " ", str(text))[:1500]}\n')
    except OSError:
        pass


def fehler_merken(art, text, wo='', lex=''):
    try:
        os.makedirs(DATEN, exist_ok=True)
        with open(F_FEHLER, 'a', encoding='utf-8') as f:
            f.write(json.dumps({'zeit': jetzt(), 'art': art, 'text': str(text)[:600], 'wo': str(wo)[:120], 'lex': lex}, ensure_ascii=False) + '\n')
    except OSError:
        pass


def lies(p, sonst=None):
    try:
        with open(p, encoding='utf-8') as f:
            return json.load(f)
    except OSError:
        return sonst
    except ValueError:
        gut = p + '.gut'
        if os.path.exists(gut):
            shutil.copy2(p, p + '.kaputt-' + datetime.datetime.now().strftime('%Y%m%d-%H%M%S'))
            shutil.copy2(gut, p)
            fehler_merken('server', f'{os.path.basename(p)} war beschädigt, die letzte gute Fassung ist zurück', 'lies', 'stand-kaputt')
            with open(p, encoding='utf-8') as f:
                return json.load(f)
        raise Fehler(f'BESCHAEDIGT · Die Datei {os.path.basename(p)} ist beschädigt und es gibt keine Sicherung. Nichts wurde überschrieben.', 'stand-kaputt', 500)


def schreib(p, d):
    os.makedirs(os.path.dirname(p), exist_ok=True)
    roh = json.dumps(d, ensure_ascii=False, indent=1)
    if os.path.exists(p):
        try:
            json.load(open(p, encoding='utf-8'))
            shutil.copy2(p, p + '.gut')
        except (OSError, ValueError):
            pass
    tmp = p + '.neu'
    with open(tmp, 'w', encoding='utf-8') as f:
        f.write(roh)
    os.replace(tmp, p)


def tief(a, b):
    return json.dumps(a, sort_keys=True, ensure_ascii=False) == json.dumps(b, sort_keys=True, ensure_ascii=False)


def kopie(d):
    return json.loads(json.dumps(d))


def leer(v):
    return v is None or v == '' or (isinstance(v, (dict, list)) and not v)


def stand():
    d = lies(F_STAND, None)
    return d if isinstance(d, dict) else {}


def entwurf():
    d = lies(F_ENTWURF, None)
    if isinstance(d, dict):
        return d
    e = kopie(stand())
    e.pop('_meta', None)
    return e


def ohne_privat(c):
    return {k: v for k, v in c.items() if not k.startswith('_')}


def fingerabdruck(c):
    return hashlib.sha1(json.dumps(ohne_privat(c), sort_keys=True, ensure_ascii=False).encode('utf-8')).hexdigest()[:16]


def schritt_sichern(c):
    os.makedirs(SCHRITTE, exist_ok=True)
    sid = datetime.datetime.now().strftime('%Y%m%d-%H%M%S-%f')
    schreib(os.path.join(SCHRITTE, sid + '.json'), c)
    for alt in sorted(os.listdir(SCHRITTE))[:-80]:
        try:
            os.remove(os.path.join(SCHRITTE, alt))
        except OSError:
            pass
    return sid


# ------------------------------------------------------------------ Lesbare Namen statt interner Schlüssel (Meldungen, Liste «Änderungen», Verlauf)
FELD_DE = {'cost': 'Versandkosten', 'freeFrom': 'Versandkostenfrei ab', 'handlingDays': 'Bearbeitung', 'insured': 'Versichert', 'regions': 'Länder und Laufzeiten',
           'returnDays': 'Rückgabefrist', 'band': 'Hinweis-Leiste', 'entwurf': 'Entwurfs-Hinweis', 'de': 'Deutsch', 'tagline': 'Claim', 'description': 'Beschreibung'}


def feldname(teil, k):
    """«Versand: handlingDays» → «Versand: Bearbeitung», «Angaben: legalName» → «Angaben: Firmenname»; Seiten (Google) und Bilder bleiben, wie sie sind."""
    k = str(k)
    if teil in ('seo', 'bilder', 'alt'):
        return k
    return FELD_DE.get(k) or S.SCHLUESSEL_DE.get(k) or k


def wert_text(v, txt):
    """Werte lesbar: 4.9 → 4,90, true/false → ja/nein, Länderliste → «2 Einträge»."""
    if isinstance(v, bool):
        return 'ja' if v else 'nein'
    if isinstance(v, float):
        return (f'{v:.2f}'.replace('.', ',')) if v != int(v) else str(int(v))
    if isinstance(v, list):
        return f'{len(v)} Einträge' if len(v) != 1 else '1 Eintrag'
    return txt


# ------------------------------------------------------------------ Unterschied Stand ↔ Entwurf (eine Zeile je Stelle)
def unterschied(s, e):
    aus = []
    for teil in TEILE:
        a, b = s.get(teil), e.get(teil)
        if tief(a, b):
            continue
        if teil == 'texte':
            ka = {(x.get('seite') or '*') + '|' + x.get('alt', ''): x for x in a or []}
            kb = {(x.get('seite') or '*') + '|' + x.get('alt', ''): x for x in b or []}
            for k in list(dict.fromkeys(list(ka) + list(kb))):
                if tief(ka.get(k), kb.get(k)):
                    continue
                seite, alt = k.split('|', 1)
                aus.append({'teil': teil, 'schluessel': [seite, alt], 'titel': 'Text überall' if seite == '*' else 'Text auf ' + seite,
                            'text': alt[:70] + (' → ' + kb[k]['neu'][:70] if kb.get(k) else ' zurückgesetzt'), 'vorher': alt, 'nachher': kb[k]['neu'] if kb.get(k) else alt, 'seite': seite})
        elif teil == 'produkte':
            for slug in dict.fromkeys(list(a or {}) + list(b or {})):
                if not tief((a or {}).get(slug), (b or {}).get(slug)):
                    aa, bb = (a or {}).get(slug) or {}, (b or {}).get(slug) or {}
                    f = [k for k in dict.fromkeys(list(aa) + list(bb)) if not tief(aa.get(k), bb.get(k))]
                    aus.append({'teil': teil, 'schluessel': slug, 'titel': 'Produkt ' + slug, 'text': ', '.join(f) or 'zurück auf den Code'})
        elif teil == 'neu_produkte':
            sa, sb = {x.get('slug'): x for x in a or []}, {x.get('slug'): x for x in b or []}
            for slug in dict.fromkeys(list(sa) + list(sb)):
                if not tief(sa.get(slug), sb.get(slug)):
                    aus.append({'teil': teil, 'schluessel': slug, 'titel': 'Neues Produkt ' + str(slug), 'text': 'angelegt' if slug not in sa else 'gelöscht' if slug not in sb else 'geändert'})
        elif teil == 'aus':
            for k in dict.fromkeys(list(a or {}) + list(b or {})):
                if not tief((a or {}).get(k), (b or {}).get(k)):
                    seite, txt = (k.split('|', 1) + [''])[:2]
                    aus.append({'teil': teil, 'schluessel': k, 'titel': 'Ausgeblendet auf ' + seite, 'text': txt[:80] + ('' if (b or {}).get(k) else ' · wieder gezeigt'), 'seite': seite})
        elif teil in DICT_TEILE:
            for k in dict.fromkeys(list(a or {}) + list(b or {})):
                if not tief((a or {}).get(k), (b or {}).get(k)):
                    v = (b or {}).get(k)
                    vor = (a or {}).get(k)
                    txt = 'zurückgesetzt' if v is None else (json.dumps(v, ensure_ascii=False) if isinstance(v, (dict, list)) else str(v))
                    aus.append({'teil': teil, 'schluessel': k, 'titel': TEILNAME[teil] + ': ' + feldname(teil, k), 'text': wert_text(v, txt)[:80],
                                'vorher': '' if vor is None else (json.dumps(vor, ensure_ascii=False) if isinstance(vor, (dict, list)) else str(vor)), 'nachher': '' if v is None else txt,
                                'seite': k if teil == 'seo' else '*'})
        else:
            aus.append({'teil': teil, 'schluessel': '', 'titel': TEILNAME[teil], 'text': 'geändert' if not leer(b) else 'zurück auf den Code'})
    return aus


# ------------------------------------------------------------------ Eingaben prüfen (Bausteine, Länge, Form)
def sauber(t, max_=TEXT_MAX, feld='Text'):
    t = re.sub(r'<[^>]*>', '', str(t if t is not None else ''))
    t = ''.join(ch for ch in t if ch == '\n' or ch == '\t' or ord(ch) >= 32)
    t = I.norm(t)
    if len(t) > max_:
        raise Fehler(f'EINGABE · {feld} ist zu lang ({len(t)} Zeichen, höchstens {max_}).', 'zu-lang')
    return t


def preis(x, feld='Preis'):
    if x is None or x == '':
        return None
    if isinstance(x, (int, float)):
        return round(float(x) * 100) / 100
    s = str(x).strip().replace('€', '').replace(' ', '')
    s = s.replace('.', '').replace(',', '.') if ',' in s and '.' in s else s.replace(',', '.')
    try:
        v = float(s)
    except ValueError:
        raise Fehler(f'{feld} muss eine Zahl sein, zum Beispiel 69 oder 39,50.', 'zahl-format')
    if v < 0 or v > 100000:
        raise Fehler(f'{feld} muss zwischen 0 und 100.000 liegen.', 'zahl-format')
    return round(v * 100) / 100


MAIL = re.compile(r'^[^\s@"<>]+@[^\s@"<>]+\.[a-z]{2,}$', re.I)
TEL = re.compile(r'^\+?[\d ()/\-]{6,}$')
LINK = re.compile(r'^https://[^\s"\'<>`\\]+$')


def pruef_angaben(daten):
    aus = {}
    for k, v in (daten or {}).items():
        if not re.fullmatch(r'[A-Za-z]{2,40}', str(k)):
            raise Fehler('EINGABE · Unbekannte Angabe.', 'anfrage')
        if isinstance(v, dict):
            v = {kk: sauber(vv, 600, S.SCHLUESSEL_DE.get(k, k)) for kk, vv in v.items() if kk in ('en', 'de')}
            if not any(v.values()):
                v = ''
        else:
            v = sauber(v, 600, S.SCHLUESSEL_DE.get(k, k))
        if isinstance(v, str) and v:
            if k.lower().endswith('email') and not MAIL.match(v):
                raise Fehler(f'{S.SCHLUESSEL_DE.get(k, k)}: keine gültige E-Mail-Adresse (name@txtme.social).', 'mail-format')
            if k == 'url' and not LINK.match(v):
                raise Fehler('Die Adresse der Website muss mit https:// beginnen und darf keine Leerzeichen haben.', 'link-format')
            if k == 'phone' and not TEL.match(v):
                raise Fehler('Die Telefonnummer darf nur Ziffern, Leerzeichen, Klammern und + enthalten.', 'tel-format')
        aus[k] = v
    return aus


def pruef_band(b):
    b = b or {}
    h = {k: sauber(b.get(k), 300 if k == 'text' else 200, {'text': 'Text der Hinweis-Leiste', 'link': 'Link der Hinweis-Leiste', 'linktext': 'Linktext der Hinweis-Leiste'}.get(k, 'Datum')) for k in ('text', 'link', 'linktext', 'von', 'bis')}
    h['an'] = bool(b.get('an'))
    h['farbe'] = b.get('farbe') if b.get('farbe') in I.BAND_FARBE else 'ink'
    h['groesse'] = b.get('groesse') if b.get('groesse') in I.BAND_GROESSE else 'mittel'
    for k in ('von', 'bis'):
        if h[k] and not re.fullmatch(r'\d{4}-\d{2}-\d{2}', h[k]):
            raise Fehler('EINGABE · Datum als Jahr-Monat-Tag wählen (das Feld hat einen Kalender).', 'datum-format')
    if h['von'] and h['bis'] and h['bis'] < h['von']:
        raise Fehler('EINGABE · «Bis» liegt vor «Ab».', 'datum-format')
    if h['link'] and not re.match(r'^(https://[^\s]+|/[^\s]*|mailto:[^\s]+|tel:[^\s]+)$', h['link']):
        raise Fehler('Der Link beginnt mit https:// oder ist eine Seite der Website, zum Beispiel /merch/.', 'link-format')
    if h['an'] and not h['text']:
        raise Fehler('EINGABE · Die Hinweis-Leiste braucht einen Text, bevor sie eingeschaltet wird.', 'pflichtfeld')
    return h if (h['an'] or h['text']) else ''


def pruef_bildpfad(p):
    p = str(p or '')
    if not p:
        return ''
    if not re.fullmatch(r'/media/[\w\-./]+\.(webp|jpg|jpeg|png|svg|gif)', p, re.I) or '..' in p:
        raise Fehler('BILD · Die Bildadresse muss mit /media/ beginnen (ein Bild der Website oder ein hochgeladenes).', 'link-format')
    rel = p[len('/media/'):]
    if not (os.path.exists(os.path.join(UPLOADS, rel[2:])) if rel.startswith('u/') else (os.path.exists(os.path.join(ROOT, 'public', 'media', rel)) or os.path.exists(os.path.join(OUT, 'media', rel)))):
        raise Fehler('BILD · Dieses Bild gibt es nicht in den Bildern der Website.', 'veraltet')
    return p


def pruef_tiefe(d, tiefe=0):
    if tiefe > 8:
        raise Fehler('EINGABE · Die Daten sind zu tief verschachtelt.', 'anfrage')
    if isinstance(d, dict):
        if len(d) > 2000:
            raise Fehler('EINGABE · Zu viele Einträge.', 'anfrage')
        for v in d.values():
            pruef_tiefe(v, tiefe + 1)
    elif isinstance(d, list):
        if len(d) > 2000:
            raise Fehler('EINGABE · Zu viele Einträge.', 'anfrage')
        for v in d:
            pruef_tiefe(v, tiefe + 1)
    elif isinstance(d, str) and len(d) > 200000:
        raise Fehler('EINGABE · Ein Wert ist zu lang.', 'zu-lang')


# ------------------------------------------------------------------ Ändern (Entwurf), Zurücknehmen, Verwerfen, Rückgängig
def aendern(teil, daten, wer):
    if teil not in TEILE:
        raise Fehler('Unbekannte Eingabe.', 'anfrage')
    if teil in MEDUSA:
        raise Fehler('MEDUSA · Produkte, Preise und Kategorien pflegt das txtme-Team im Medusa-Panel. Backstage ändert sie nicht.', 'medusa')
    pruef_tiefe(daten)
    with SCHLOSS:
        e = entwurf()
        vorher = kopie(e)
        ge = []
        if teil == 'texte':
            if not isinstance(daten, list):
                raise Fehler('Unbekannte Eingabe.', 'anfrage')
            t = e.get('texte') or []
            for x in daten:
                alt, seite = I.norm(x.get('alt')), str(x.get('seite') or '*')
                if not alt:
                    raise Fehler('Der Text darf nicht leer sein.', 'pflichtfeld')
                if seite != '*' and not re.fullmatch(r'/[\w\-./]*', seite):
                    raise Fehler('Unbekannte Seite.', 'anfrage')
                t = [y for y in t if not (y.get('alt') == alt and (y.get('seite') or '*') == seite)]
                if x.get('neu') is not None:
                    neu = sauber(x.get('neu'))
                    if not neu:
                        raise Fehler('EINGABE · Ein Text darf nicht leer sein. Um etwas wegzunehmen: den Satz kurz fassen oder zurücksetzen.', 'pflichtfeld')
                    if neu != alt:
                        t.append({'seite': seite, 'alt': alt, 'neu': neu})
                        ge.append(('Text überall: ' if seite == '*' else 'Text auf ' + seiten_name(seite) + ': ') + neu[:40])   # Quittung: Name der Seite und der neue Text
                    else:
                        ge.append('Text wie ursprünglich: ' + alt[:40])
                else:
                    ge.append('Text zurückgesetzt: ' + alt[:40])
            e['texte'] = t
            if not t:
                e.pop('texte', None)
        elif teil in DICT_TEILE:
            if not isinstance(daten, dict):
                raise Fehler('Unbekannte Eingabe.', 'anfrage')
            if teil == 'angaben':
                daten = pruef_angaben(daten)
            if teil == 'band':
                daten = {'band': pruef_band(daten)}
            o = e.get(teil) or {}
            for k, v in daten.items():
                k = str(k)[:300]
                if teil == 'bilder':
                    v = pruef_bildpfad(v)
                if teil == 'alt':
                    v = sauber(v, 300, 'Bildbeschreibung')
                if teil == 'seo' and isinstance(v, dict):
                    v = {kk: sauber(v.get(kk), 120 if kk == 'title' else 400, 'Google-Text') for kk in ('title', 'description') if v.get(kk)}
                if teil == 'versand' and k in ('freeFrom', 'cost') and v not in ('', None):
                    v = preis(v, k)
                if teil == 'woerter' and isinstance(v, dict):
                    v = {I.norm(kk)[:TEXT_MAX]: sauber(vv) for kk, vv in v.items() if I.norm(kk) and sauber(vv)}
                if teil == 'hinweis' and k == 'entwurf' and v not in ('', None):
                    v = bool(v)
                if teil == 'aus' and not leer(v):
                    seite, txt = (k.split('|', 1) + [''])[:2]
                    if not re.fullmatch(r'/[\w\-./]*', seite) or not I.norm(txt):
                        raise Fehler('Unbekannte Eingabe.', 'anfrage')
                    kk = seite.strip('/')
                    if not os.path.exists(os.path.join(I.OUT, kk, 'index.html') if kk else os.path.join(I.OUT, 'index.html')):
                        raise Fehler('Unbekannte Seite.', 'anfrage')
                    if True:
                        if not I.ausblendbar(kk, I.norm(txt)):
                            raise Fehler('AUSBLENDEN · Dieser Satz steht nicht allein in seinem Baustein; ausblenden geht hier nicht, ändern schon.', 'aus-geht-nicht')
                    v = True
                if leer(v):
                    if k in o:
                        del o[k]
                        ge.append(f'Wieder gezeigt auf {k.split("|", 1)[0]}: {k.split("|", 1)[1][:60]}' if teil == 'aus' else TEILNAME[teil] + ': ' + feldname(teil, k) + ' zurückgesetzt')
                elif not tief(o.get(k), v):
                    o[k] = v
                    ge.append(f'Ausgeblendet auf {k.split("|", 1)[0]}: {k.split("|", 1)[1][:60]}' if teil == 'aus' else TEILNAME[teil] + ': ' + feldname(teil, k))
            e[teil] = o
            if not o:
                e.pop(teil, None)
        else:   # fragen, presse, recht, zahlarten: ganzer Block
            if leer(daten):
                if teil in e:
                    e.pop(teil, None)
                    ge.append(TEILNAME[teil] + ' zurück auf den Code')
            else:
                daten = json.loads(json.dumps(daten))
                _texte_saeubern(daten)
                if not tief(e.get(teil), daten):
                    e[teil] = daten
                    ge.append(TEILNAME[teil] + ' geändert')
        if not ge or tief(ohne_privat(e), ohne_privat(vorher)):
            return {'ok': True, 'nichts': True, 'titel': 'Nichts geändert, nichts gespeichert.', 'text': '', 'basis': fingerabdruck(vorher)}
        sid = schritt_sichern(vorher)
        e['_aenderungen'] = (e.get('_aenderungen') or [])[-199:] + [{'zeit': jetzt()[:19], 'teil': teil, 'was': ge[:12], 'wer': wer['name']}]
        schreib(F_ENTWURF, e)
        protokoll(wer['name'], wer['rolle'], 'Entwurf gespeichert: ' + '; '.join(ge)[:600])
        aussen = []
        for g in nicht_auf_website(ohne_privat(stand()), ohne_privat(e), None, teil).values():
            aussen.extend(g)
        return {'ok': True, 'nichts': False, 'titel': 'Gespeichert, im Entwurf.', 'text': ' · '.join(ge[:6]), 'geaendert': ge, 'schritt': sid, 'basis': fingerabdruck(e),
                'aussen': list(dict.fromkeys(aussen))[:8]}


def _texte_saeubern(d):
    if isinstance(d, dict):
        for k, v in list(d.items()):
            if isinstance(v, str):
                d[k] = sauber(v) if k not in ('href', 'id', 'date') else v[:500]
            else:
                _texte_saeubern(v)
    elif isinstance(d, list):
        for i, v in enumerate(d):
            if isinstance(v, str):
                d[i] = sauber(v)
            else:
                _texte_saeubern(v)


def seiten_name(pfad):
    """Name der Seite für Meldungen («Home» statt «/»)."""
    try:
        for x in I.inventar()['seiten']:
            if x['pfad'] == pfad:
                return x['name']
    except Exception:
        pass
    return pfad


def zuruecknehmen(teil, k, wer):
    with SCHLOSS:
        s, e = stand(), entwurf()
        if teil not in TEILE:
            raise Fehler('Unbekannte Eingabe.', 'anfrage')
        schritt_sichern(e)
        if teil in DICT_TEILE or teil == 'produkte':
            if s.get(teil) and k in s[teil]:
                e[teil] = e.get(teil) or {}
                e[teil][k] = s[teil][k]
            elif e.get(teil):
                e[teil].pop(k, None)
            if teil in e and not e[teil]:
                del e[teil]
        elif teil == 'neu_produkte':
            e[teil] = [x for x in e.get(teil) or [] if x.get('slug') != k] + [x for x in s.get(teil) or [] if x.get('slug') == k]
            if not e[teil]:
                del e[teil]
        elif teil == 'texte':
            seite, alt = (k[0], k[1]) if isinstance(k, list) and len(k) == 2 else ('*', str(k))
            e['texte'] = [x for x in e.get('texte') or [] if not ((x.get('seite') or '*') == seite and x.get('alt') == alt)] + \
                [x for x in s.get('texte') or [] if (x.get('seite') or '*') == seite and x.get('alt') == alt]
            if not e['texte']:
                del e['texte']
        else:
            if teil in s:
                e[teil] = kopie(s[teil])
            else:
                e.pop(teil, None)
        schreib(F_ENTWURF, e)
        protokoll(wer['name'], wer['rolle'], f'Zurückgenommen: {teil} {k}')
        was = (f'{k[1]} ({"alle Seiten" if k[0] == "*" else seiten_name(k[0])})' if teil == 'texte' and isinstance(k, list) and len(k) == 2 else (k if isinstance(k, str) else ' '.join(map(str, k))))
        return {'ok': True, 'titel': 'Zurückgenommen.', 'text': TEILNAME[teil] + ': ' + was, 'basis': fingerabdruck(e)}


def verwerfen(wer):
    with SCHLOSS:
        e = entwurf()
        schritt_sichern(e)
        s = kopie(stand())
        s.pop('_meta', None)
        schreib(F_ENTWURF, s)
        protokoll(wer['name'], wer['rolle'], 'Entwurf verworfen (aufgehoben in schritte/)')
        return {'ok': True, 'titel': 'Entwurf verworfen.', 'text': 'Der Entwurf ist wieder der veröffentlichte Stand. «Rückgängig» holt ihn aus den Schritten zurück.', 'basis': fingerabdruck(s)}


def rueckgaengig(sid, wer):
