# ------------------------------------------------------------------ Veröffentlichen: Probe-Bau, Prüfung, Verlauf, Übernehmen, Nachprüfen
def verlauf_liste():
    if not os.path.isdir(VERLAUF):
        return []
    aus = []
    for f in sorted((x for x in os.listdir(VERLAUF) if x.endswith('.json')), reverse=True):
        d = lies(os.path.join(VERLAUF, f), {}) or {}
        aus.append({'id': f[:-5], 'zeit': d.get('zeit') or '', 'notiz': d.get('notiz') or '', 'anzahl': d.get('anzahl', 0), 'aenderungen': (d.get('aenderungen') or [])[:40],
                    'wer': d.get('wer', ''), 'dateien': os.path.isdir(os.path.join(VERLAUF, f[:-5] + '-dateien'))})
    return aus


def _lauf(t):
    LAUF['schritt'] = t
    LAUF['schritte'].append({'t': t, 'zeit': round(time.time() - LAUF['start'], 1)})


def veroeffentlichen(notiz, wer):
    with SCHLOSS:
        if LAUF['laeuft']:
            raise Fehler('LAEUFT · Es wird gerade veröffentlicht. Einen Moment.', 'bau-laeuft', 409)
        s, e = stand(), entwurf()
        diff = unterschied(s, e)
        if not diff:
            raise Fehler('Es gibt nichts zu veröffentlichen: Der Entwurf ist gleich dem veröffentlichten Stand.', 'nichts-offen')
        if not I.seiten_liste():
            raise Fehler('BAU · Es gibt keine gebaute Website (out/ fehlt). Im Projektordner «npm run build» laufen lassen, dann veröffentlichen.', 'bau-fehler')
        LAUF.update(laeuft=True, schritt='', schritte=[], fertig=None, fehler='', start=time.time(), um=time.time())
    threading.Thread(target=_veroeffentlichen, args=(e, s, diff, sauber(notiz, 300, 'Notiz'), wer), daemon=True).start()
    return {'ok': True, 'laeuft': True, 'zahl': len(diff), 'titel': 'Wird veröffentlicht …', 'text': f'{len(diff)} Änderungen werden auf einer Probe gesetzt und geprüft.'}


def _veroeffentlichen(e, s, diff, notiz, wer):
    zeit = datetime.datetime.now().strftime('%Y-%m-%d_%H%M%S')
    neu_dir = os.path.join(BAU, 'neu-' + zeit)
    sicher = os.path.join(VERLAUF, zeit + '-dateien')
    uebernommen = False
    try:
        _lauf('Prüfen, was sich geändert hat')
        c = ohne_privat(e)
        cd = I.code()
        seiten = I.seiten_liste()
        _lauf(f'{len(seiten)} Seiten mit dem Entwurf auf einer Probe setzen')
        os.makedirs(neu_dir, exist_ok=True)
        benutzt, inhalte = set(), {}
        for k, pfad, datei in seiten:
            ziel = os.path.join(neu_dir, k) if k else neu_dir
            os.makedirs(ziel, exist_ok=True)
            html = I.seite_mit(k, c, 'html', 'live', cd, benutzt)
            inhalte[os.path.join(ziel, 'index.html')] = html
            if os.path.exists(os.path.join(os.path.dirname(datei), 'index.txt')):
                inhalte[os.path.join(ziel, 'index.txt')] = I.seite_mit(k, c, 'txt', 'live', cd, benutzt)
        for p, t in inhalte.items():
            with open(p, 'w', encoding='utf-8') as f:
                f.write(t)
        _lauf('Prüfen: jede Seite ganz, keine Kennzeichen der Vorschau, keine Seite geschrumpft, jede Änderung hat ihre Stelle')
        bef, hinweise = [], []
        for k, pfad, datei in seiten:
            p = os.path.join(neu_dir, k, 'index.html') if k else os.path.join(neu_dir, 'index.html')
            t = inhalte[p]
            if not t.rstrip().endswith('</html>'):
                bef.append(f'{pfad}: Seite endet nicht sauber.')
            if 'bs-vorschau' in t or 'id="bs-neu"' in t:
                bef.append(f'{pfad}: Kennzeichen der Vorschau in der Seite.')
            if len(t.encode('utf-8')) < os.path.getsize(datei) * 0.6:
                bef.append(f'{pfad}: Seite ist um mehr als 40 % kleiner geworden.')
        for r in I.regeln(c, cd):
            k = (r['teil'], json.dumps(r['schl'], ensure_ascii=False))
            if k not in benutzt:
                if r['teil'] in ('texte', 'bilder', 'alt', 'aus'):
                    bef.append(f'{TEILNAME[r["teil"]]} «{str(r.get("alt") or r.get("src"))[:50]}» hat seine Stelle auf keiner Seite gefunden (die Seite wurde inzwischen neu gebaut). Unter «Änderungen» zurücknehmen oder neu machen.')
                else:
                    hinweise.append(f'{TEILNAME[r["teil"]]}: «{str(r.get("alt") or "")[:60]}» steht so auf keiner gebauten Seite; diese Stelle ändert sich nicht.')
        # Was nicht auf die Website kommt (Neues, Gelöschtes, Reihenfolge, deutsche Fassungen, Felder ohne Stelle) und wie viele Seiten sich wirklich ändern
        for g in nicht_auf_website(ohne_privat(s), c, cd).values():
            hinweise.extend(g)
        hinweise = list(dict.fromkeys(hinweise))
        geaendert = 0
        for k, pfad, datei in seiten:
            p = os.path.join(neu_dir, k, 'index.html') if k else os.path.join(neu_dir, 'index.html')
            q = os.path.join(LIVE, k, 'index.html') if k else os.path.join(LIVE, 'index.html')
            jetzt_da = q if os.path.exists(q) else datei
            with open(jetzt_da, encoding='utf-8') as f:
                if f.read() != inhalte[p]:
                    geaendert += 1
        bef = list(dict.fromkeys(bef))
        if bef:
            raise Fehler('PRUEFUNG · ' + ' · '.join(bef[:6]), 'pruefung-rot')
        _lauf('Alte Fassung in den Verlauf sichern')
        os.makedirs(VERLAUF, exist_ok=True)
        if os.path.isdir(LIVE):
            shutil.copytree(LIVE, sicher, dirs_exist_ok=True)
        else:
            os.makedirs(sicher, exist_ok=True)
        if os.path.exists(F_STAND):
            shutil.copy2(F_STAND, os.path.join(sicher, '_stand.json'))
        _lauf(f'Übernehmen: {len(inhalte)} Dateien')
        neu = dict(c, _meta={'stand': jetzt()[:19], 'notiz': notiz, 'aenderungen': diff[:60], 'wer': wer['name']})
        with SCHLOSS:
            uebernommen = True
            schreib(F_STAND, neu)
            if os.path.isdir(LIVE):
                shutil.rmtree(LIVE)
            shutil.move(neu_dir, LIVE)
            ent = kopie(neu)
            ent.pop('_meta', None)
            schreib(F_ENTWURF, ent)
            schreib(os.path.join(VERLAUF, zeit + '.json'), {'id': zeit, 'zeit': neu['_meta']['stand'], 'notiz': notiz, 'anzahl': len(diff), 'aenderungen': diff[:40], 'daten': neu, 'wer': wer['name']})
        _lauf('Nachprüfen: jede übernommene Datei Byte für Byte')
        for p, t in inhalte.items():
            q = p.replace(neu_dir, LIVE, 1)
            with open(q, encoding='utf-8') as f:
                if f.read() != t:
                    raise Fehler(f'NACHPRUEFUNG · {os.path.relpath(q, LIVE)} ist nach dem Übernehmen nicht gleich wie geprüft.', 'pruefung-rot')
        alt = sorted(x for x in os.listdir(VERLAUF) if x.endswith('.json'))
        for a in alt[:-40]:
            try:
                os.remove(os.path.join(VERLAUF, a))
                shutil.rmtree(os.path.join(VERLAUF, a[:-5] + '-dateien'), ignore_errors=True)
            except OSError:
                pass
        I.inventar(True)
        protokoll(wer['name'], wer['rolle'], f'Veröffentlicht {zeit}: {len(diff)} Änderungen, {len(inhalte)} Dateien' + (f', Notiz «{notiz}»' if notiz else ''))
        LAUF.update(fertig={'zeit': jetzt(), 'zahl': len(diff), 'dateien': len(inhalte), 'id': zeit, 'aenderungen': mit_aussen(diff, ohne_privat(s), c)[:60], 'hinweise': hinweise[:12],
                            'seiten_geaendert': geaendert})
    except Exception as ex:  # noqa: BLE001
        if uebernommen:
            try:
                if os.path.isdir(LIVE):
                    shutil.rmtree(LIVE)
                if os.path.isdir(sicher):
                    shutil.copytree(sicher, LIVE, dirs_exist_ok=True)
                    try:
                        os.remove(os.path.join(LIVE, '_stand.json'))
                    except OSError:
                        pass
                if os.path.exists(os.path.join(sicher, '_stand.json')):
                    shutil.copy2(os.path.join(sicher, '_stand.json'), F_STAND)
                else:
                    try:
                        os.remove(F_STAND)
                    except OSError:
                        pass
                try:
                    os.remove(os.path.join(VERLAUF, zeit + '.json'))
                except OSError:
                    pass
                schreib(F_ENTWURF, e)
            except Exception as ex2:  # noqa: BLE001
                fehler_merken('server', 'Zurückstellen gescheitert: ' + str(ex2)[:300], 'veroeffentlichen', 'serverfehler')
        shutil.rmtree(neu_dir, ignore_errors=True)
        meldung = str(ex) if isinstance(ex, Fehler) else 'SERVER · ' + str(ex)[:300]
        lex = ex.lex if isinstance(ex, Fehler) else 'serverfehler'
        fehler_merken('server', 'Veröffentlichen gescheitert: ' + meldung, 'veroeffentlichen', lex)
        protokoll(wer['name'], wer['rolle'], 'Veröffentlichen gescheitert, Website unverändert' + (' (zurückgestellt)' if uebernommen else ''))
        if not isinstance(ex, Fehler):
            fehler_merken('server', traceback.format_exc()[-900:], 'veroeffentlichen', 'serverfehler')
        LAUF.update(fehler=meldung + ' Die Website ist unverändert.', lex=lex)
    finally:
        LAUF['laeuft'] = False


