# ------------------------------------------------------------------ Bilder: hochladen, Bibliothek
def bild(name, daten, wer):
    from PIL import Image, ImageOps
    try:
        roh = base64.b64decode(str(daten or '').split(',', 1)[-1])
    except (ValueError, TypeError):
        raise Fehler('BILD · Die Datei kam nicht vollständig an.', 'datei-art')
    if len(roh) > 25 * 1024 * 1024:
        raise Fehler('BILD · Das Bild ist grösser als 25 MB. Bitte kleiner exportieren.', 'datei-gross')
    try:
        im = ImageOps.exif_transpose(Image.open(io.BytesIO(roh)))
        im.load()
    except Exception:  # noqa: BLE001
        raise Fehler('BILD · Das ist kein Bild, das wir lesen können (JPG, PNG oder WebP; HEIC vorher als JPG sichern).', 'datei-art')
    if im.width < 900:
        raise Fehler(f'BILD · Das Bild ist nur {im.width} Pixel breit. Für die Website braucht es mindestens 900, besser 2000.', 'bild-klein')
    alpha = im.mode in ('RGBA', 'LA') or (im.mode == 'P' and 'transparency' in im.info)
    im = im.convert('RGBA' if alpha else 'RGB')
    slug = re.sub(r'[^a-z0-9]+', '-', os.path.splitext(str(name or 'bild'))[0].lower()).strip('-')[:40] or 'bild'
    key = f'{slug}-{datetime.datetime.now().strftime("%m%d%H%M%S")}'
    os.makedirs(UPLOADS, exist_ok=True)
    w = min(2000, im.width)
    gross = im.resize((w, round(im.height * w / im.width)), Image.LANCZOS) if im.width > w else im
    gross.save(os.path.join(UPLOADS, key + '.webp'), 'WEBP', quality=84, method=6)
    for b in (1400, 900):
        if gross.width > b:
            gross.resize((b, round(gross.height * b / gross.width)), Image.LANCZOS).save(os.path.join(UPLOADS, f'{key}-{b}.webp'), 'WEBP', quality=82, method=6)
    reg = lies(F_BILDER, {}) or {}
    reg[key] = {'w': gross.width, 'h': gross.height, 'datei': str(name or '')[:120], 'hochgeladen': jetzt(), 'wer': wer['name']}
    schreib(F_BILDER, reg)
    protokoll(wer['name'], wer['rolle'], f'Bild hochgeladen: {key} ({gross.width} × {gross.height})')
    klein = f'/media/u/{key}-900.webp' if gross.width > 900 else f'/media/u/{key}.webp'
    return {'ok': True, 'pfad': f'/media/u/{key}.webp', 'klein': klein, 'breite': gross.width, 'hoehe': gross.height, 'eigen': True}


_BIB = {'schluessel': None, 'wert': None}


def bilder_bibliothek():
    """Alle Bilder der Website (public/media) und die hochgeladenen (public/media/u): Quelle, Masse, Vorschau, benutzt auf Seiten."""
    basis = os.path.join(ROOT, 'public', 'media')
    if not os.path.isdir(basis):
        basis = os.path.join(OUT, 'media')
    dateien = []
    for d, dirs, files in os.walk(basis):
        dirs.sort()
        for f in sorted(files):
            if re.search(r'\.(webp|jpe?g|png|svg|gif)$', f, re.I):
                p = os.path.join(d, f)
                dateien.append((p, os.path.getmtime(p), os.path.getsize(p)))
    if os.path.isdir(UPLOADS) and not UPLOADS.startswith(basis):
        for f in sorted(os.listdir(UPLOADS)):
            if re.search(r'\.(webp|jpe?g|png)$', f, re.I):
                p = os.path.join(UPLOADS, f)
                dateien.append((p, os.path.getmtime(p), os.path.getsize(p)))
    schl = tuple(dateien)
    if _BIB['schluessel'] == schl:
        return _BIB['wert']
    benutzt = {}
    for s in I.inventar()['seiten']:
        for b in s['bilder']:
            benutzt.setdefault(b['src'], []).append(s['pfad'])
    aus = []
    try:
        from PIL import Image
    except ImportError:
        Image = None
    for p, mt, gr in dateien:
        if p.startswith(UPLOADS):
            src = '/media/u/' + os.path.basename(p)
        else:
            src = '/media/' + os.path.relpath(p, basis).replace(os.sep, '/')
        if re.search(r'-(900|1400)\.webp$', src) and src.startswith('/media/u/'):
            continue
        w = h = 0
        if Image and not src.endswith('.svg'):
            try:
                with Image.open(p) as im:
                    w, h = im.size
            except Exception:  # noqa: BLE001
                continue
        name = os.path.basename(src)
        aus.append({'src': src, 'name': name, 'ordner': src.split('/')[2] if src.count('/') > 2 else '', 'w': w, 'h': h, 'kb': round(gr / 1024), 'eigen': src.startswith('/media/u/'),
                    'benutzt': benutzt.get(src, []), 'klein': src})
    aus.sort(key=lambda x: (not x['eigen'], not x['benutzt'], x['src']))
    _BIB['schluessel'], _BIB['wert'] = schl, aus
    return aus


# ------------------------------------------------------------------ Überblick, Daten, Vergleich, Angaben, Sprachen
def inventar():
    return I.inventar()


def wirksam(cd, s):
    w = kopie(cd)
    for teil in TEILE:
        if teil in s and not leer(s[teil]):
            if isinstance(w.get(teil), dict) and isinstance(s[teil], dict) and teil not in ('fragen', 'presse', 'recht'):
                w[teil] = dict(w[teil], **s[teil])
            elif teil in ('fragen', 'presse', 'recht') and isinstance(w.get(teil), dict) and isinstance(s[teil], dict):
                w[teil] = kopie(w[teil])
                for k, v in s[teil].items():
                    if teil == 'presse' and isinstance(v, dict) and isinstance(w[teil].get(k), dict):
                        w[teil][k] = dict(w[teil][k], **v)
                    else:
                        w[teil][k] = v
            else:
                w[teil] = s[teil]
    a = w.get('angaben') or {}
    w['site'] = dict(cd.get('site') or {}, **{k: (a[k].get('en') if isinstance(a.get(k), dict) else a[k]) for k in ('tagline', 'description') if a.get(k)})
    return w


VERSAND_NAME = {'cost': 'Versandkosten', 'freeFrom': 'Versandkostenfrei ab', 'handlingDays': 'Bearbeitung', 'insured': 'Versichert', 'regions': 'Länder und Laufzeiten'}


def _ids(liste):
    return [x.get('id') for x in liste or [] if isinstance(x, dict)]


def nicht_auf_website(s, e, cd=None, nur_teil=None):
    """Je Änderung (teil, schluessel) die Gründe, warum sie nicht oder nur teilweise auf die gebaute Website kommt.
    Die Website steht auf Englisch und ist fertig gebaut: die Schicht ersetzt, was auf den Seiten schon steht; Neues, Gelöschtes,
    eine neue Reihenfolge und deutsche Fassungen brauchen den nächsten Bau. Ehrlich vor dem Speichern, im Entwurf und nach dem Veröffentlichen."""
    cd = I.code() if cd is None else cd
    aus = {}

    def merk(teil, schl, text):
        if nur_teil and teil != nur_teil:
            return
        aus.setdefault((teil, json.dumps(schl, ensure_ascii=False)), []).append(text)
    v, sv = e.get('versand') or {}, s.get('versand') or {}
    for k, name in VERSAND_NAME.items():
        if not tief(v.get(k), sv.get(k)) and not leer(v.get(k)):
            merk('versand', k, f'«{name}» steht so nicht auf der Website; die Seite «Shipping & Payments» behält ihren Wortlaut.')
    if not tief(v.get('returnDays'), sv.get('returnDays')) and not leer(v.get('returnDays')) and I.tage(v.get('returnDays')) is None:
        merk('versand', 'returnDays', 'Die Rückgabefrist braucht eine ganze Zahl von 1 bis 365 Tagen; so bleibt die Seite bei ihrer Frist.')
    if not tief(e.get('woerter'), s.get('woerter')) and not leer(e.get('woerter')):
        for sp in (e.get('woerter') or {}):
            merk('woerter', sp, 'Deutsche Fassungen werden aufgehoben, aber die Website steht nur auf Englisch: sie erscheinen nirgends.')
    # Fragen und Presse: bestehende Einträge ändern geht, Neues, Gelöschtes und eine neue Reihenfolge nicht
    cf, sf, ef = cd.get('fragen') or {}, s.get('fragen') or cd.get('fragen') or {}, e.get('fragen')
    if ef is not None and not tief(ef, s.get('fragen')):
        for sp, gruppen in (ef or {}).items():
            if not tief(gruppen, sf.get(sp)):
                if sp != 'en':
                    merk('fragen', '', 'Deutsche Fragen erscheinen nicht, die Website steht auf Englisch.')
                    continue
                cg = {g.get('id'): g for g in cf.get(sp) or []}
                sg = {g.get('id'): g for g in sf.get(sp) or []}
                for g in gruppen or []:
                    if g.get('id') not in cg:
                        if tief(g, sg.get(g.get('id'))) is False or g.get('id') not in sg:
                            merk('fragen', '', f'Neue Gruppe «{I.norm(g.get("title"))[:60]}» kommt nicht auf die Support-Seite.')
                        continue
                    ci = {x.get('id') for x in cg[g['id']].get('items') or []}
                    si = {x.get('id'): x for x in (sg.get(g['id']) or {}).get('items') or []}
                    for it in g.get('items') or []:
                        if it.get('id') not in ci and (it.get('id') not in si or not tief(it, si.get(it.get('id')))):
                            merk('fragen', '', f'Neue Frage «{I.norm(it.get("q"))[:80]}» kommt nicht auf die Support-Seite.')
                    ei = set(_ids(g.get('items')))
                    for it in cg[g['id']].get('items') or []:
                        if it.get('id') not in ei:
                            merk('fragen', '', f'Gelöschte Frage «{I.norm(it.get("q"))[:80]}» bleibt auf der Support-Seite.')
                    gem = [x for x in _ids(g.get('items')) if x in ci]
                    if gem != [x for x in _ids(cg[g['id']].get('items')) if x in ei]:
                        merk('fragen', '', f'Die neue Reihenfolge in «{I.norm(g.get("title"))[:60]}» kommt nicht auf die Support-Seite.')
                eg = set(_ids(gruppen))
                for g in cf.get(sp) or []:
                    if g.get('id') not in eg:
                        merk('fragen', '', f'Gelöschte Gruppe «{I.norm(g.get("title"))[:60]}» bleibt auf der Support-Seite.')
                if [x for x in _ids(gruppen) if x in cg] != [x for x in _ids(cf.get(sp)) if x in eg]:
                    merk('fragen', '', 'Die neue Reihenfolge der Gruppen kommt nicht auf die Support-Seite.')
    cp, sp_, ep = cd.get('presse') or {}, s.get('presse') or cd.get('presse') or {}, e.get('presse')
    if ep is not None and not tief(ep, s.get('presse')):
        for sp, liste in (ep.get('eintraege') or {}).items():
            if tief(liste, (sp_.get('eintraege') or {}).get(sp)):
                continue
            if sp != 'en':
                merk('presse', '', 'Deutsche Meldungen erscheinen nicht, die Website steht auf Englisch.')
                continue
            ci = set(_ids((cp.get('eintraege') or {}).get(sp)))
            for x in liste or []:
                if x.get('id') not in ci:
                    merk('presse', '', f'Neue Meldung «{I.norm(x.get("title"))[:80]}» kommt nicht auf die Presse-Seite.')
            for x in (cp.get('eintraege') or {}).get(sp) or []:
                if x.get('id') not in set(_ids(liste)):
                    merk('presse', '', f'Gelöschte Meldung «{I.norm(x.get("title"))[:80]}» bleibt auf der Presse-Seite.')
            gem = [i for i in _ids(liste) if i in ci]
            if gem != [i for i in _ids((cp.get('eintraege') or {}).get(sp)) if i in set(_ids(liste))]:
                merk('presse', '', 'Die neue Reihenfolge der Meldungen kommt nicht auf die Presse-Seite.')
        for sp, liste in (ep.get('kit') or {}).items():
            if tief(liste, (sp_.get('kit') or {}).get(sp)):
                continue
            if sp != 'en':
                merk('presse', '', 'Deutsches Pressematerial erscheint nicht, die Website steht auf Englisch.')
                continue
            ck = (cp.get('kit') or {}).get(sp) or []
            for x in (liste or [])[len(ck):]:
                merk('presse', '', f'Neues Material «{I.norm(x.get("label"))[:60]}» kommt nicht auf die Presse-Seite.')
            if len(liste or []) < len(ck):
                merk('presse', '', 'Gelöschtes Material bleibt auf der Presse-Seite.')
    # Rechtliches: Wortlaut ändern geht (auch Überschriften, die Nummer setzt die Seite selbst); neue oder gelöschte Abschnitte und Absätze nicht
    for art, doc in (e.get('recht') or {}).items():
        if tief(doc, (s.get('recht') or {}).get(art)):
            continue
        ad = (cd.get('recht') or {}).get(art) or {}
        asec, esec = ad.get('sections') or [], (doc or {}).get('sections') or []
        name = 'Terms of Service' if art == 'terms' else 'Privacy Policy' if art == 'privacy' else art
        if len(esec) > len(asec):
            merk('recht', '', f'{len(esec) - len(asec)} neue(r) Abschnitt(e) in «{name}» kommen nicht auf die Seite.')
        if len(esec) < len(asec):
            merk('recht', '', f'Gelöschte Abschnitte in «{name}» bleiben auf der Seite.')
        for i, sec in enumerate(esec[:len(asec)]):
            a = asec[i]
            if I.recht_nummer(a.get('heading')) != I.recht_nummer(sec.get('heading')):
                merk('recht', '', f'Die Nummer der Überschrift «{I.norm(sec.get("heading"))[:60]}» setzt die Website selbst; sie bleibt «{I.recht_nummer(a.get("heading")) or "ohne Nummer"}».')
            ab, eb = a.get('blocks') or [], sec.get('blocks') or []
            if len(eb) != len(ab) or any(('ul' in x) != ('ul' in y) or len(x.get('ul') or []) != len(y.get('ul') or []) for x, y in zip(eb, ab)):
                merk('recht', '', f'Neue oder gelöschte Absätze und Listenpunkte in «{I.norm(sec.get("heading") or name)[:60]}» kommen nicht auf die Seite; geänderter Wortlaut schon.')
    # Zahlarten: Name, Hinweis, Länder gehen; ausschalten nicht
    sz = {z.get('id'): z for z in s.get('zahlarten') or []}
    for z in e.get('zahlarten') or []:
        if z.get('aktiv') is False and (sz.get(z.get('id')) or {}).get('aktiv') is not False:
            merk('zahlarten', '', f'Ausgeschaltete Zahlart «{I.norm(z.get("label"))}» bleibt auf der Seite.')
    # Angaben, die im Code leer sind, stehen auf keiner Seite
    ca = cd.get('angaben') or {}
    for k, val in (e.get('angaben') or {}).items():
        if k in ('tagline', 'description'):
            continue
        if not tief(val, (s.get('angaben') or {}).get(k)) and not leer(val) and not (ca.get(k) or ''):
            merk('angaben', k, f'«{S.SCHLUESSEL_DE.get(k, k)}» ist auf der Website leer gebaut und steht darum auf keiner Seite.')
    b = (e.get('band') or {}).get('band') or {}
    if not tief(e.get('band'), s.get('band')) and b and not b.get('an'):
        merk('band', 'band', 'Die Hinweis-Leiste ist ausgeschaltet und steht auf keiner Seite.')
    return aus


def mit_aussen(diff, s, e):
    """Hängt an jede Änderung die Gründe, warum sie (teilweise) nicht auf die Website kommt."""
    na = nicht_auf_website(s, e)
    for d in diff:
        g = na.get((d['teil'], json.dumps(d['schluessel'], ensure_ascii=False)))
        if g:
            d['aussen'] = list(dict.fromkeys(g))
    return diff


