def vergleich(seite):
    k = (seite or '').strip('/')
    pfad = '/' + k + '/' if k else '/'
    inv = inventar()
    s = next((x for x in inv['seiten'] if x['pfad'] == pfad), None)
    texte = {t['text'] for t in (s['texte'] if s else [])}
    bilder = {b['src'] for b in (s['bilder'] if s else [])}
    e, st = ohne_privat(entwurf()), ohne_privat(stand())
    vor, nach, bv, bn = [], [], [], []
    rs, re_ = {(r['art'], r['seite'], r.get('alt') or r.get('src')): r for r in I.regeln(st)}, I.regeln(e)
    for r in re_:
        alt = rs.get((r['art'], r['seite'], r.get('alt') or r.get('src')))
        if alt and alt.get('neu') == r.get('neu'):
            continue
        if r['art'] == 'text' and (r['seite'] == pfad or (r['seite'] == '*' and r['alt'] in texte)):
            vor.append(r['alt'])
            nach.append(r['neu'])
        if r['art'] == 'bild' and r['alt'] in bilder:
            bv.append(r['alt'])
            bn.append(r['neu'])
    return {'vorher': vor, 'nachher': nach, 'bilder_vorher': bv, 'bilder_nachher': bn, 'seite': pfad}


def angaben_zaehl():
    """Je Angabe: steht n× auf m Seiten (aus dem Inventar der gebauten Seiten, wie Le Bureau E)."""
    cd = I.code()
    inv = inventar()
    werte = dict(cd.get('angaben') or {})
    site = cd.get('site') or {}
    werte['tagline'], werte['description'] = site.get('tagline', ''), site.get('description', '')
    aus = {}
    for k, v in werte.items():
        if not isinstance(v, str) or not v:
            aus[k] = {'mal': 0, 'seiten': 0, 'wert': v}
            continue
        mal, seiten = 0, 0
        for s in inv['seiten']:
            n = sum(t['n'] for t in s['texte'] if t['text'] == v or v in t['text'])
            if n:
                mal += n
                seiten += 1
        aus[k] = {'mal': mal, 'seiten': seiten, 'wert': v}
    return aus


def sprachen_liste():
    """Jedes geänderte englische Stück (Texte, Hinweis-Leiste) und seine Übersetzung je zweiter Sprache (Deutsch); nichts wird geraten."""
    e = ohne_privat(entwurf())
    w = e.get('woerter') or {}
    aus, gesehen = [], set()
    stuecke = [(t.get('neu'), 'Text auf ' + (t.get('seite') if t.get('seite') not in (None, '*') else 'allen Seiten'), t.get('alt')) for t in e.get('texte') or []]
    b = (e.get('band') or {}).get('band') or {}
    if b.get('text'):
        stuecke.append((b['text'], 'Hinweis-Leiste', ''))
        if b.get('linktext'):
            stuecke.append((b['linktext'], 'Hinweis-Leiste', ''))
    for en, wo, vorher in stuecke:
        en = I.norm(en)
        if not en or en in gesehen:
            continue
        gesehen.add(en)
        aus.append({'en': en, 'wo': wo, 'vorher_en': vorher or '', 'sp': {sp: {'wert': (w.get(sp) or {}).get(en, '')} for sp in SPRACHEN}})
    return aus


