# ------------------------------------------------------------------ Prüfung und Reparaturen
def pruefung():
    t0 = time.time()
    p = []

    def punkt(id_, titel, grad, text, tun=None):
        p.append({'id': id_, 'titel': titel, 'ok': grad == 'gruen', 'grad': grad, 'text': text, 'tun': tun})
    punkt('version', 'Backstage-Server', 'gruen', f'Fassung {VERSION}, Daten in {DATEN}, Port {PORT}, KI aus (ki={KI}).')
    seiten = I.seiten_liste()
    inv = inventar()
    if seiten:
        punkt('bau', 'Gebaute Website (out/)', 'gruen', f'{len(seiten)} Seiten, Inventar mit {sum(len(s["texte"]) for s in inv["seiten"])} Texten und {sum(len(s["bilder"]) for s in inv["seiten"])} Bildern.')
    else:
        punkt('bau', 'Gebaute Website (out/)', 'rot' if inv['wurzel'] == 'leer' else 'gelb', 'Kein Bau in out/. Im Projektordner «npm run build» laufen lassen; bis dahin ' + ('ist nichts zu bedienen.' if inv['wurzel'] == 'leer' else 'zeigt Backstage den Schnappschuss vom 10.10.2026.'), 'bau-entwurf')
    for f, name in ((F_STAND, 'Veröffentlichter Stand (stand.json)'), (F_ENTWURF, 'Entwurf (entwurf.json)')):
        if not os.path.exists(f):
            punkt(os.path.basename(f), name, 'gruen', 'Noch nichts gespeichert, die Website zeigt sich wie gebaut.')
            continue
        try:
            json.load(open(f, encoding='utf-8'))
            punkt(os.path.basename(f), name, 'gruen', f'lesbar, {os.path.getsize(f) // 1024 + 1} KB, Sicherung {"da" if os.path.exists(f + ".gut") else "noch keine"}.')
        except ValueError:
            punkt(os.path.basename(f), name, 'rot', 'Die Datei ist beschädigt.', 'zurueck-' + os.path.basename(f))
    z = WACHE.stand({'name': '', 'rolle': '', 'angemeldet': False})
    punkt('zugang', 'Zugang', 'gelb' if z['offen'] else 'gruen', ('Ohne Passwort offen (bis zur Auslieferung, nur an diesem Rechner).' if not z['eingerichtet'] else 'Notausgang-Datei inhalt/offen liegt da: Backstage ist trotz Benutzern offen.') if z['offen'] else f'{len(z["benutzer"])} Benutzer mit Rollen, Anmeldung vor dem Werkzeug.')
    try:
        s = ohne_privat(stand())
        if s and seiten:
            abw = []
            for k, pfad, datei in seiten[:40]:
                q = os.path.join(LIVE, k, 'index.html') if k else os.path.join(LIVE, 'index.html')
                soll = I.seite_mit(k, s, 'html', 'live')
                if not os.path.exists(q) or open(q, encoding='utf-8').read() != soll:
                    abw.append(pfad)
            punkt('live', 'Website zeigt den veröffentlichten Stand', 'gruen' if not abw else 'rot', 'ja, Seite für Seite verglichen.' if not abw else 'weicht ab: ' + ', '.join(abw[:6]), 'bau-stand' if abw else None)
        else:
            punkt('live', 'Website zeigt den veröffentlichten Stand', 'gruen', 'Noch nichts veröffentlicht, die Website zeigt sich wie gebaut.')
    except Exception as ex:  # noqa: BLE001
        punkt('live', 'Website zeigt den veröffentlichten Stand', 'gelb', str(ex)[:200])
    try:
        e = ohne_privat(entwurf())
        benutzt = set()
        for k, pfad, datei in seiten:
            I.seite_mit(k, e, 'html', 'live', None, benutzt)
        verwaist = [r for r in I.regeln(e) if (r['teil'], json.dumps(r['schl'], ensure_ascii=False)) not in benutzt and r['teil'] in ('texte', 'bilder', 'alt')]
        punkt('verwaist', 'Jede Änderung findet ihre Stelle', 'gruen' if not verwaist else 'gelb', 'ja.' if not verwaist else f'{len(verwaist)} Änderung(en) ohne Stelle (die Seite wurde inzwischen neu gebaut): unter «Änderungen» zurücknehmen oder neu machen.')
    except Exception as ex:  # noqa: BLE001
        punkt('verwaist', 'Jede Änderung findet ihre Stelle', 'gelb', str(ex)[:200])
    vl = verlauf_liste()
    punkt('verlauf', 'Verlauf', 'gruen', f'{len(vl)} Veröffentlichung(en) aufgehoben (die letzten 40)' + (f', zuletzt {vl[0]["zeit"]}' if vl else '') + '.')
    punkt('schritte', 'Rückgängig-Schritte', 'gruen', f'{len(os.listdir(SCHRITTE)) if os.path.isdir(SCHRITTE) else 0} aufgehoben (die letzten 80).')
    if LAUF['laeuft']:
        punkt('lauf', 'Veröffentlichen', 'gelb', 'läuft gerade: ' + LAUF['schritt'])
    elif LAUF['fehler']:
        punkt('lauf', 'Letztes Veröffentlichen', 'rot', LAUF['fehler'])
    reste = [d for d in os.listdir(BAU)] if os.path.isdir(BAU) else []
    punkt('baurest', 'Bauordner aufgeräumt', 'gruen' if not reste else 'gelb', 'leer.' if not reste else f'{len(reste)} Rest(e) von abgebrochenen Läufen.', 'bau-aufraeumen' if reste else None)
    reg = lies(F_BILDER, {}) or {}
    punkt('uploads', 'Hochgeladene Bilder', 'gruen', f'{len(reg)} Bild(er) unter public/media/u/, neu kodiert als WebP (2000/1400/900).')
    punkt('medusa', 'Produkte, Preise, Kategorien', 'gruen', 'Pflegt das txtme-Team im Medusa-Panel. Backstage zeigt den Katalog nur (Schnappschuss ' + str(I.katalog().get('stand', '')) + ').')
    punkt('wache', 'Sicherheit', 'gruen', 'Host 421, fremde Herkunft 403, 600 lesen / 60 schreiben je Minute (429), Anfragen bis 32 MB (413), Rollen admin/redaktion/lesen (403), Protokoll mit Namen.')
    fehler = []
    try:
        for zeile in open(F_FEHLER, encoding='utf-8', errors='replace').read().strip().splitlines()[-30:][::-1]:
            try:
                fehler.append(json.loads(zeile))
            except ValueError:
                fehler.append({'zeit': '', 'art': 'server', 'text': zeile[:300], 'wo': '', 'lex': ''})
    except OSError:
        pass
    return {'zeit': jetzt(), 'dauer': round(time.time() - t0, 2), 'punkte': p, 'fehler': fehler, 'offen': WACHE.offen(), 'version': VERSION, 'protokoll': protokoll_lesen()}


def protokoll_lesen(n=30):
    try:
        return open(F_PROT, encoding='utf-8', errors='replace').read().strip().splitlines()[-n:][::-1]
    except OSError:
        return []


def reparieren(tun, wer):
    if tun in ('zurueck-stand.json', 'zurueck-entwurf.json'):
        f = F_STAND if tun.endswith('stand.json') else F_ENTWURF
        if not os.path.exists(f + '.gut'):
            raise Fehler('SICHERUNG · Es gibt keine Sicherung (.gut) dieser Datei.', 'stand-kaputt')
        if os.path.exists(f):
            shutil.copy2(f, f + '.kaputt-' + datetime.datetime.now().strftime('%Y%m%d-%H%M%S'))
        shutil.copy2(f + '.gut', f)
        protokoll(wer['name'], wer['rolle'], 'Reparatur: ' + tun)
        return {'ok': True, 'text': 'Letzte gute Fassung zurück, die beschädigte ist als .kaputt aufgehoben.'}
    if tun == 'stand-anlegen':
        if not os.path.exists(F_STAND):
            schreib(F_STAND, {})
            return {'ok': True, 'text': 'Leerer Stand angelegt.'}
        return {'ok': True, 'text': 'Der Stand war schon da, nichts geändert.'}
    if tun == 'entwurf-verwerfen':
        verwerfen(wer)
        return {'ok': True, 'text': 'Entwurf verworfen (in den Schritten aufgehoben).'}
    if tun == 'bau-entwurf':
        I.inventar(True)
        return {'ok': True, 'text': 'Der Entwurf wird bei jedem Aufruf frisch über die gebaute Seite gelegt, nichts zu bauen. Inventar neu gelesen: ' + str(len(I.inventar()['seiten'])) + ' Seiten.'}
    if tun == 'bau-stand':
        s = ohne_privat(stand())
        if not s:
            return {'ok': True, 'text': 'Noch nichts veröffentlicht: die Website zeigt sich wie gebaut, nichts zu setzen.'}
        if LAUF['laeuft']:
            raise Fehler('LAEUFT · Es wird gerade veröffentlicht.', 'bau-laeuft', 409)
        n = 0
        for k, pfad, datei in I.seiten_liste():
            ziel = os.path.join(LIVE, k) if k else LIVE
            os.makedirs(ziel, exist_ok=True)
            for art, name in (('html', 'index.html'), ('txt', 'index.txt')):
                if art == 'txt' and not os.path.exists(os.path.join(os.path.dirname(datei), 'index.txt')):
                    continue
                with open(os.path.join(ziel, name), 'w', encoding='utf-8') as f:
                    f.write(I.seite_mit(k, s, art, 'live'))
                n += 1
        protokoll(wer['name'], wer['rolle'], f'Reparatur: veröffentlichte Seiten neu gesetzt ({n} Dateien)')
        return {'ok': True, 'text': f'{n} Dateien aus dem Stand neu gesetzt.'}
    if tun == 'bau-aufraeumen':
        if LAUF['laeuft']:
            raise Fehler('LAEUFT · Es wird gerade veröffentlicht.', 'bau-laeuft', 409)
        shutil.rmtree(BAU, ignore_errors=True)
        return {'ok': True, 'text': 'Bauordner leer.'}
    if tun == 'uploads-aufraeumen':
        benutzt = set()
        for c in [stand(), entwurf()] + [(lies(os.path.join(VERLAUF, f), {}) or {}).get('daten') or {} for f in os.listdir(VERLAUF) if f.endswith('.json')] if os.path.isdir(VERLAUF) else [stand(), entwurf()]:
            benutzt |= set(re.findall(r'/media/u/([\w\-]+?)(?:-\d+)?\.webp', json.dumps(c)))
        weg = 0
        for f in os.listdir(UPLOADS) if os.path.isdir(UPLOADS) else []:
            key = re.sub(r'(-\d+)?\.webp$', '', f)
            if key not in benutzt:
                os.remove(os.path.join(UPLOADS, f))
                weg += 1
        reg = {k: v for k, v in (lies(F_BILDER, {}) or {}).items() if k in benutzt}
        schreib(F_BILDER, reg)
        _BIB['schluessel'] = None
        return {'ok': True, 'text': f'{weg} Datei(en) gelöscht, die nirgends mehr vorkommen.'}
    if tun == 'fehler-leeren':
        open(F_FEHLER, 'w').close()
        return {'ok': True, 'text': 'Fehlerprotokoll geleert.'}
    raise Fehler('Unbekannte Reparatur.', 'anfrage')


