_FASSUNG = {}


def mit_fassung(html, basis):
    """?v=1 → ?v=<Prüfsumme des Inhalts>, damit der Browser nach jeder Änderung die neue Datei holt (M20)."""
    def f(m):
        p = os.path.join(basis, m.group(2))
        try:
            mt = os.path.getmtime(p)
            if _FASSUNG.get(p, (None,))[0] != mt:
                _FASSUNG[p] = (mt, hashlib.sha1(open(p, 'rb').read()).hexdigest()[:10])
            return f'{m.group(1)}{m.group(2)}?v={_FASSUNG[p][1]}"'
        except OSError:
            return m.group(0)
    return re.sub(r'((?:href|src)=")([\w\-./]+\.(?:css|js))\?v=\w+"', f, html)


WACHE = Wache(DATEN, PORT, protokoll)
CSP = "default-src 'self'; img-src 'self' data: blob:; style-src 'self' 'unsafe-inline'; script-src 'self'; frame-src 'self'; connect-src 'self'; form-action 'self'; base-uri 'self'; frame-ancestors 'self'; object-src 'none'"


class Handler(BaseHTTPRequestHandler):
    server_version = 'Backstage/' + VERSION
    protocol_version = 'HTTP/1.1'

    def log_message(self, *a):
        pass

    # ---------- Antworten
    def _kopf(self, status, typ, laenge, extra=None, cache='no-store'):
        self.send_response(status)
        self.send_header('Content-Type', typ)
        self.send_header('Content-Length', str(laenge))
        self.send_header('Cache-Control', cache)
        self.send_header('X-Content-Type-Options', 'nosniff')
        self.send_header('Referrer-Policy', 'same-origin')
        self.send_header('X-Frame-Options', 'SAMEORIGIN')
        for k, v in (extra or {}).items():
            self.send_header(k, v)
        if self.close_connection:
            self.send_header('Connection', 'close')
        self.end_headers()

    def _json(self, status, d, extra=None):
        if (self.headers.get('X-Backstage-Sprache') or '').lower() != 'de':   # Oberfläche Englisch (Auftrag Regel 3), Deutsch per Knopf
            d = S.en(d, urlsplit(self.path).path.rstrip('/').rsplit('/', 1)[-1])
        roh = json.dumps(d, ensure_ascii=False).encode('utf-8')
        self._kopf(status, 'application/json; charset=utf-8', len(roh), extra)
        if self.command != 'HEAD':
            self.wfile.write(roh)

    def _text(self, status, t, typ='text/html; charset=utf-8', extra=None, cache='no-store'):
        roh = t.encode('utf-8') if isinstance(t, str) else t
        self._kopf(status, typ, len(roh), extra, cache)
        if self.command != 'HEAD':
            self.wfile.write(roh)

    def _datei(self, p, extra=None):
        if not os.path.isfile(p):
            return False
        typ = mimetypes.guess_type(p)[0] or 'application/octet-stream'
        if typ.startswith('text/') or typ in ('application/javascript', 'application/json', 'image/svg+xml'):
            typ += '; charset=utf-8'
        cache = 'public, max-age=31536000, immutable' if '/_next/static/' in p else 'no-cache'
        with open(p, 'rb') as f:
            self._text(200, f.read(), typ, extra, cache)
        return True

    def _kekse(self):
        c = cookies.SimpleCookie()
        try:
            c.load(self.headers.get('Cookie') or '')
        except cookies.CookieError:
            return {}
        return {k: v.value for k, v in c.items()}

    def _ip(self):
        return self.client_address[0]

    # ---------- Wege
    def do_HEAD(self):
        self.do_GET()

    def do_GET(self):
        try:
            self._get()
        except Abgewiesen as e:
            self._json(e.status, {'fehler': str(e), 'lex': e.lex}, e.kopf)
        except Fehler as e:
            self._json(e.status, {'fehler': str(e), 'lex': e.lex})
        except (BrokenPipeError, ConnectionResetError):
            pass
        except Exception as e:  # noqa: BLE001
            fehler_merken('server', str(e)[:300] + ' | ' + traceback.format_exc()[-600:], self.path[:80], 'serverfehler')
            try:
                self._json(500, {'fehler': 'SERVER · ' + str(e)[:200], 'lex': 'serverfehler'})
            except Exception:  # noqa: BLE001
                pass

    def _sicher(self, basis, rel):
        rel = unquote(rel).lstrip('/')
        p = os.path.normpath(os.path.join(basis, rel))
        if not p.startswith(os.path.abspath(basis)) or '\x00' in rel:
            return None
        return p

    def _get(self):
        u = urlsplit(self.path)
        pfad, q = unquote(u.path), parse_qs(u.query)
        if pfad.startswith('/backstage/api/') or pfad.startswith('/backstage'):
            WACHE.host_pruefen(self.headers.get('Host'))
        if pfad.startswith('/backstage/api/'):
            WACHE.grenze(WACHE.absender(self._ip(), self._kekse()), False)
            weg = re.sub(r'[^a-z_]', '', pfad[len('/backstage/api/'):])
            wer = WACHE.wer(self._kekse())
            if weg not in ('zugang', 'pruefung', 'bau') and not wer['angemeldet']:
                raise Abgewiesen(401, 'ANMELDUNG · Bitte anmelden.', 'anmeldung')
            return self._json(200, get(weg, q, wer))
        if pfad == '/backstage':
            return self._text(301, '', extra={'Location': '/backstage/'})
        if pfad.startswith('/backstage/'):
            rel = pfad[len('/backstage/'):] or 'index.html'
            if rel.endswith('/'):
                rel += 'index.html'
            p = self._sicher(OBERFLAECHE, rel)
            if p and rel.endswith('.html') and os.path.isfile(p):   # Fassungsnummer aus dem Inhalt (M20): ?v=<hash> je Datei, nie von Hand
                with open(p, encoding='utf-8') as f:
                    return self._text(200, mit_fassung(f.read(), os.path.dirname(p)), extra={'Content-Security-Policy': CSP})
            if p and self._datei(p):
                return
            return self._text(404, 'Not found.', 'text/plain; charset=utf-8')
        if pfad.startswith('/werkbank/anleitung'):
            return self._datei(os.path.join(OBERFLAECHE, 'anleitung', 'index.html'), {'Content-Security-Policy': CSP}) or self._text(404, 'Not found.', 'text/plain; charset=utf-8')
        if pfad == '/katalog.json':
            return self._json(200, I.katalog())
        if pfad == '/backstage.json':
            return self._json(200, {'daten': {'code': I.code()}})
        if pfad.startswith('/media/u/'):
            p = self._sicher(UPLOADS, pfad[len('/media/u/'):])
            if p and self._datei(p):
                return
            return self._text(404, 'Not found.', 'text/plain; charset=utf-8')
        # Website. Rahmen (Sec-Fetch-Dest iframe) unter /entwurf/ und /vorher/ bekommen eine stille Momentaufnahme; ein Reiter bekommt einen Keks
        # und den echten Pfad (sonst scheitert die Hydration von React am Pfad-Präfix, Probe 06.11.2026); ?bs=aus nimmt den Keks weg.
        kekse = self._kekse()
        modus, wurzel = 'live', ''
        m = re.match(r'^/(entwurf|vorher)(/.*)?$', pfad)
        if m:
            pfad = m.group(2) or '/'
            art_ = 'entwurf' if m.group(1) == 'entwurf' else 'stand'
            if (self.headers.get('Sec-Fetch-Dest') or '').lower() == 'document' and not pfad.endswith('.txt'):
                return self._text(302, '', extra={'Location': pfad, 'Set-Cookie': f'bs_modus={art_}; Path=/; SameSite=Lax; HttpOnly'})
            modus, wurzel = art_, '/' + m.group(1)
        elif q.get('bs_rahmen', [''])[0] == 'entwurf' and (self.headers.get('Sec-Fetch-Dest') or '').lower() == 'iframe':
            modus = 'js-entwurf'   # Seitenansicht und Vorschau in Backstage: echte Seite mit Skripten unter dem echten Pfad, Entwurf darübergelegt
        elif q.get('bs', [''])[0] == 'aus':
            return self._text(302, '', extra={'Location': pfad, 'Set-Cookie': 'bs_modus=; Path=/; Max-Age=0; SameSite=Lax; HttpOnly'})
        elif kekse.get('bs_modus') in ('entwurf', 'stand'):
            modus = 'keks-' + kekse['bs_modus']
        rel = pfad.strip('/')
        letzter = rel.split('/')[-1]
        if rel and letzter not in ('index.html', 'index.txt') and '.' in letzter:   # Datei (Bild, Skript, Stil, Datenstrom des Routers)
            p = self._sicher(OUT, rel)
            if p and self._datei(p):
                return
            return self._text(404, 'Not found.', 'text/plain; charset=utf-8')
        art = 'txt' if letzter == 'index.txt' else 'html'
        k = re.sub(r'/?index\.(html|txt)$', '', rel).strip('/')
        if k and not re.fullmatch(r'[\w\-/]+', k):
            return self._text(404, 'Not found.', 'text/plain; charset=utf-8')
        typ = 'text/plain; charset=utf-8' if art == 'txt' else 'text/html; charset=utf-8'
        f_live = os.path.join(LIVE, k, 'index.' + art) if k else os.path.join(LIVE, 'index.' + art)
        quelle = os.path.join(OUT, k, 'index.' + art) if k else os.path.join(OUT, 'index.' + art)
        if not os.path.isfile(quelle):
            if art == 'html' and os.path.isfile(os.path.join(OUT, '404.html')):
                with open(os.path.join(OUT, '404.html'), encoding='utf-8') as f:
                    return self._text(404, f.read())
            return self._text(404, 'Not found.', 'text/plain; charset=utf-8')
        pf = '/' + k + '/' if k else '/'
        if modus == 'live':
            return self._datei(f_live if os.path.isfile(f_live) else quelle)
        if modus in ('stand', 'keks-stand'):
            with open(f_live if os.path.isfile(f_live) else quelle, encoding='utf-8') as f:
                return self._text(200, I.anwenden(f.read(), pf, {}, art, modus, None, None, wurzel), typ)
        marken = q.get('marken', [''])[0] == '1'
        return self._text(200, I.seite_mit(k, ohne_privat(entwurf()), art, modus, None, None, wurzel, None, marken), typ)

    def do_POST(self):
        try:
            self._post()
        except Abgewiesen as e:
            self._json(e.status, {'fehler': str(e), 'lex': e.lex}, e.kopf)
        except Fehler as e:
            self._json(e.status, {'fehler': str(e), 'lex': e.lex})
        except (BrokenPipeError, ConnectionResetError):
            pass
        except Exception as e:  # noqa: BLE001
            fehler_merken('server', str(e)[:300] + ' | ' + traceback.format_exc()[-600:], self.path[:80], 'serverfehler')
            try:
                self._json(500, {'fehler': 'SERVER · ' + str(e)[:200], 'lex': 'serverfehler'})
            except Exception:  # noqa: BLE001
                pass

    def _post(self):
        u = urlsplit(self.path)
        pfad = unquote(u.path)
        if not pfad.startswith('/backstage/api/'):
            return self._text(404, 'Not found.', 'text/plain; charset=utf-8')
        laenge = int(self.headers.get('Content-Length') or 0)
        try:
            WACHE.groesse_pruefen(laenge)
        except Abgewiesen:
            self.close_connection = True   # der Rumpf wird nie gelesen: Verbindung zu, sonst liest der nächste Aufruf auf derselben Verbindung seine Reste
            raise
        roh = self.rfile.read(laenge) if laenge else b'{}'   # erst ganz lesen, dann prüfen (bleibt der Rumpf liegen, verdirbt er die nächste Anfrage auf der Verbindung, Probe 06.11.2026)
        WACHE.host_pruefen(self.headers.get('Host'))
        WACHE.herkunft_pruefen(self.headers.get('Origin'), self.headers.get('Referer'), self.headers.get('Host'))
        if self.headers.get('X-Backstage') != '1':
            raise Abgewiesen(403, 'HERKUNFT · Die Anfrage kommt nicht von Backstage selbst und wurde abgewiesen.', 'herkunft')
        WACHE.grenze(WACHE.absender(self._ip(), self._kekse()), True)
        if 'application/json' not in (self.headers.get('Content-Type') or ''):
            raise Abgewiesen(415, 'EINGABE · Nur JSON.', 'anfrage')
        try:
            d = json.loads(roh.decode('utf-8') or '{}')
        except (ValueError, UnicodeDecodeError):
            raise Abgewiesen(400, 'EINGABE · Die Anfrage ist kein lesbares JSON.', 'anfrage')
        if not isinstance(d, dict):
            raise Abgewiesen(400, 'EINGABE · Die Anfrage ist kein lesbares JSON.', 'anfrage')
        weg = re.sub(r'[^a-z_]', '', pfad[len('/backstage/api/'):])
        wer = WACHE.wer(self._kekse())
        if weg == 'zugang':
            return self._zugang(d, wer)
        WACHE.darf(wer, weg)

        def basis_pruefen(d):
            b = d.get('basis')
            if b and b != fingerabdruck(entwurf()):
                raise Fehler('KONFLIKT · In einem anderen Fenster wurde inzwischen gespeichert. Die Liste wird neu geladen; die gelben Eingaben bleiben.', 'konflikt', 409)
        return self._json(200, post(weg, d, wer, basis_pruefen))

    def _zugang(self, d, wer):
        tun = d.get('tun')
        z = WACHE.zugang()
        if tun == 'einrichten':
            if z['benutzer'] and wer['rolle'] != 'admin':
                raise Abgewiesen(403, 'ZUGANG · Backstage ist schon eingerichtet; neue Benutzer legt ein Admin unter «Zugang» an.', 'zugang')
            if z['benutzer']:
                WACHE.passwort(wer['name'], d.get('neu'), wer)
                return self._json(200, {'ok': True, 'titel': 'Passwort gesetzt.', 'text': 'Gilt ab der nächsten Anmeldung.'})
            name = (d.get('name') or 'admin').strip()
            WACHE.benutzer_neu(name, d.get('neu'), 'admin', {'name': name, 'rolle': 'admin'})
            return self._json(200, {'ok': True, 'titel': 'Passwort gesetzt.', 'text': f'Backstage fragt ab jetzt beim Öffnen danach. Benutzer «{name}» (admin).'})
        if tun == 'anmelden':
            tok, b = WACHE.anmelden(d.get('name'), d.get('pw'), self._ip())
            return self._json(200, {'ok': True, 'name': b['name'], 'rolle': b['rolle']}, {'Set-Cookie': f'bs_sitzung={tok}; Path=/backstage; HttpOnly; SameSite=Strict; Max-Age=43200'})
        if tun == 'abmelden':
            WACHE.abmelden(self._kekse().get('bs_sitzung'))
            return self._json(200, {'ok': True}, {'Set-Cookie': 'bs_sitzung=; Path=/backstage; HttpOnly; SameSite=Strict; Max-Age=0'})
        if tun == 'oeffnen':
            if wer['rolle'] != 'admin':
                raise Abgewiesen(403, 'ROLLE · Nur ein Admin kann den Passwortschutz aufheben.', 'rolle')
            WACHE.oeffnen(wer)
            return self._json(200, {'ok': True, 'titel': 'Backstage ist offen.', 'text': 'Kein Passwort mehr, alle Benutzer gelöscht.'})
        if tun == 'benutzer_neu':
            if wer['rolle'] != 'admin':
                raise Abgewiesen(403, 'ROLLE · Nur ein Admin legt Benutzer an.', 'rolle')
            WACHE.benutzer_neu(d.get('name'), d.get('pw'), d.get('rolle') or 'redaktion', wer)
            return self._json(200, {'ok': True, 'titel': 'Benutzer angelegt.', 'text': f'{d.get("name")} ({d.get("rolle") or "redaktion"})'})
        if tun == 'benutzer_weg':
            if wer['rolle'] != 'admin':
                raise Abgewiesen(403, 'ROLLE · Nur ein Admin löscht Benutzer.', 'rolle')
            WACHE.benutzer_weg(d.get('name'), wer)
            return self._json(200, {'ok': True, 'titel': 'Benutzer gelöscht.', 'text': str(d.get('name'))})
        if tun == 'passwort':
            name = d.get('name') or wer['name']
            if name.lower() != (wer['name'] or '').lower() and wer['rolle'] != 'admin':
                raise Abgewiesen(403, 'ROLLE · Das eigene Passwort ändert jeder, fremde nur ein Admin.', 'rolle')
            if not wer['angemeldet']:
                raise Abgewiesen(401, 'ANMELDUNG · Bitte anmelden.', 'anmeldung')
            WACHE.passwort(name, d.get('neu'), wer)
            return self._json(200, {'ok': True, 'titel': 'Passwort gesetzt.', 'text': name})
        raise Fehler('Unbekannte Eingabe.', 'anfrage')


def main():
    os.makedirs(DATEN, exist_ok=True)
    mimetypes.add_type('font/woff2', '.woff2')
    mimetypes.add_type('image/webp', '.webp')
    mimetypes.add_type('text/javascript', '.js')
    srv = ThreadingHTTPServer(('127.0.0.1', PORT), Handler)
    srv.daemon_threads = True
    n = len(I.seiten_liste())
    print(f'{WERKZEUG} · {NAME}  →  http://127.0.0.1:{PORT}/backstage/   (Daten: {DATEN}, {n} gebaute Seiten{"" if n else " — out/ fehlt, erst npm run build"}, KI aus)', flush=True)
    try:
        srv.serve_forever()
    except KeyboardInterrupt:
        pass


if __name__ == '__main__':
    main()

