#!/usr/bin/env python3
"""Inhalts-Schicht von Backstage (txtme.social). Daten statt Dokument (Master 2.5, L14):

Was das Team ändert, liegt als Schicht (stand.json / entwurf.json) über den gebauten Seiten in out/. Diese Datei
  - liest das INVENTAR aus den gebauten Seiten: jeder Text in Leserichtung (Tag, Bereich Kopf/Inhalt/Fuss, wie oft, auf welchen Seiten),
    jedes Bild (Quelle, Beschreibung),
  - macht aus der Schicht REGELN (Text alt → neu, Bild alt → neu, Bildbeschreibung, Angaben, Fragen, Presse, Rechtstexte, Zahlarten),
  - legt die Regeln über eine gebaute Seite (HTML, eingebetteter Datenstrom von React und index.txt, sonst setzt React den alten Text zurück),
    dazu Google-Texte, das Hinweis-Band und für die Vorschau ein kleines Skript (Links bleiben in /entwurf/, Klick meldet die Stelle an Backstage).
Ohne Änderung bleibt die Seite Byte für Byte gleich. Alles ohne Bibliothek, nur Python-Bordmittel."""
import html as _h
import json
import os
import re
from html.parser import HTMLParser

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
HIER = os.path.dirname(os.path.abspath(__file__))
OUT = os.environ.get('TXTME_OUT') or os.path.join(ROOT, 'out')
DATEN = os.path.join(HIER, 'daten')

VOID = {'img', 'br', 'hr', 'input', 'meta', 'link', 'source', 'wbr', 'area', 'base', 'col', 'embed', 'track', 'param'}
STILL = {'script', 'style', 'noscript', 'svg', 'template'}
SEITEN_WEG = {'_next', '404', '_not-found'}
NAME_SITE = 'txtme.social'


def norm(t):
    return re.sub(r'\s+', ' ', str(t or '')).strip()


def lies_json(p, sonst=None):
    try:
        with open(p, encoding='utf-8') as f:
            return json.load(f)
    except (OSError, ValueError):
        return sonst


def code():
    """Werte aus dem Code des Shops (Angaben, Versand, Zahlarten, Fragen, Presse, Rechtstexte, Farben, Kategorien), Stand 10.10.2026."""
    return lies_json(os.path.join(DATEN, 'code.json'), {}) or {}


def katalog():
    return lies_json(os.path.join(DATEN, 'katalog.json'), {'produkte': [], 'kategorien': []}) or {}


# ------------------------------------------------------------------ Inventar
class _Inventar(HTMLParser):
    def __init__(self):
        super().__init__(convert_charrefs=True)
        self.stack, self.region, self.still, self.main = [], 'main', 0, 0
        self.texte, self.bilder, self.titel, self.in_titel, self.body, self.beschr = [], [], '', False, False, ''
        self.menue_tiefe = None

    def handle_starttag(self, tag, attrs):
        a = dict(attrs)
        if tag == 'body':
            self.body = True
        if tag == 'meta' and a.get('name') == 'description':
            self.beschr = a.get('content') or ''
        if tag == 'main':
            self.main += 1
        if tag in ('header', 'footer') and not self.main:
            self.region = tag
        if a.get('role') == 'dialog' and 'menu' in (a.get('aria-label') or '').lower() and not self.main and self.region == 'main':
            self.region, self.menue_tiefe = 'header', len(self.stack)   # das aufklappbare Menü gehört zum Kopf
        if tag in STILL:
            self.still += 1
        if tag == 'title':
            self.in_titel = True
        if tag == 'img' and self.body and not self.still and a.get('src'):
            self.bilder.append({'src': a.get('src', ''), 'alt': a.get('alt', ''), 'region': self.region})
        if tag not in VOID:
            self.stack.append(tag)

    def handle_endtag(self, tag):
        if tag in STILL:
            self.still = max(0, self.still - 1)
        if tag == 'title':
            self.in_titel = False
        if tag == 'main':
            self.main = max(0, self.main - 1)
        if tag in ('header', 'footer') and not self.main:
            self.region = 'main'
        if tag in self.stack:
            while self.stack and self.stack.pop() != tag:
                pass
        if self.menue_tiefe is not None and len(self.stack) <= self.menue_tiefe:
            self.region, self.menue_tiefe = 'main', None

    def handle_data(self, data):
        if self.in_titel:
            self.titel += data
            return
        if not self.body or self.still:
            return
        t = norm(data)
        if len(t) < 2:
            return
        tag = self.stack[-1] if self.stack else 'p'
        if tag in STILL or tag == 'title':
            return
        self.texte.append({'tag': tag, 'text': t, 'region': self.region})


def seiten_liste():
    """Alle gebauten Seiten: [(k, pfad, datei)] — k '' für die Startseite, 'product/cap' für eine Produktseite."""
    aus = []
    if not os.path.isdir(OUT):
        return aus
    for d, dirs, files in os.walk(OUT):
        rel = os.path.relpath(d, OUT).replace(os.sep, '/')
        rel = '' if rel == '.' else rel
        dirs[:] = sorted(x for x in dirs if x not in SEITEN_WEG and not x.startswith('_'))
        if 'index.html' in files and rel.split('/')[0] not in SEITEN_WEG:
            aus.append((rel, '/' + rel + '/' if rel else '/', os.path.join(d, 'index.html')))
    aus.sort(key=lambda x: (x[0] != '', x[0]))
    return aus


_INV = {'schluessel': None, 'wert': None}


def _inv_schluessel():
    s = []
    for k, pfad, datei in seiten_liste():
        try:
            s.append((k, os.path.getmtime(datei), os.path.getsize(datei)))
        except OSError:
            pass
    return tuple(s)


def seitenname(k, titel):
    if not k:
        return 'Home'
    t = norm(titel)
    t = re.split(r'\s[—–|-]\s', t)[0] if t else ''
    return t or k.split('/')[-1].replace('-', ' ').title()


def inventar(frisch=False):
    """{'wurzel': 'out', 'seiten': [{k, pfad, name, titel, beschr, texte: [{tag, text, region, n, seiten, quelle?}], bilder: [...]}]}"""
    schl = _inv_schluessel()
    if not frisch and _INV['wert'] is not None and _INV['schluessel'] == schl:
        return _INV['wert']
    seiten = []
    for k, pfad, datei in seiten_liste():
        p = _Inventar()
        try:
            p.feed(open(datei, encoding='utf-8').read())
        except (OSError, UnicodeDecodeError):
            continue
        zaehl = {}
        for t in p.texte:
            key = (t['text'], t['region'], t['tag'])
            if key not in zaehl:
                zaehl[key] = dict(t, n=0)
            zaehl[key]['n'] += 1
        bilder, gesehen = [], set()
        for b in p.bilder:
            if b['src'] in gesehen or '/_next/' in b['src']:
                continue
            gesehen.add(b['src'])
            bilder.append(b)
        seiten.append({'k': k, 'pfad': pfad, 'name': seitenname(k, p.titel), 'titel': norm(p.titel), 'beschr': norm(p.beschr),
                       'texte': list(zaehl.values()), 'bilder': bilder})
    wo = {}
    for s in seiten:
        for t in s['texte']:
            wo.setdefault(t['text'], [])
            if s['pfad'] not in wo[t['text']]:
                wo[t['text']].append(s['pfad'])
    q = quellen()
    for s in seiten:
        for t in s['texte']:
            t['seiten'] = wo.get(t['text'], [s['pfad']])
            qu = q.get(t['text'])
            if qu:
                t['quelle'] = qu
    aus = {'wurzel': 'out' if seiten else 'leer', 'seiten': seiten}
    if not seiten:   # kein Bau da: das Inventar vom 10.10.2026 als Ersatz, damit Backstage bedienbar bleibt
        alt = lies_json(os.path.join(DATEN, 'inventar-2026-10-10.json'))
        if alt:
            aus = {'wurzel': 'schnappschuss', 'seiten': alt['seiten']}
    _INV['schluessel'], _INV['wert'] = schl, aus
    return aus


_QU = {'wert': None}


def quellen():
    """Text → Bereich, dem er gehört (produkte, fragen, presse, angaben, versand, zahlarten, recht): Backstage führt dann dorthin statt den Satz hier zu ändern."""
    if _QU['wert'] is not None:
        return _QU['wert']
    c, kat, m = code(), katalog(), {}

    def merk(t, teil):
        t = norm(t)
        if len(t) >= 2 and t not in m:
            m[t] = teil
    for p in kat.get('produkte') or []:
        for k in ('name', 'line', 'description', 'material'):
            v = p.get(k)
            merk(v if isinstance(v, str) else (v or {}).get('en', ''), 'produkte')
    for kg in kat.get('kategorien') or []:
        merk(kg.get('label'), 'kategorien')
    for k, v in (c.get('angaben') or {}).items():
        if isinstance(v, str):
            merk(v, 'angaben')
    for sp, gruppen in (c.get('fragen') or {}).items():
        for g in gruppen or []:
            merk(g.get('title'), 'fragen')
            for it in g.get('items') or []:
                merk(it.get('q'), 'fragen')
                merk(it.get('a'), 'fragen')
    pr = c.get('presse') or {}
    for sp, liste in (pr.get('eintraege') or {}).items():
        for e in liste or []:
            merk(e.get('title'), 'presse')
            merk(e.get('summary'), 'presse')
    for sp, liste in (pr.get('kit') or {}).items():
        for e in liste or []:
            merk(e.get('label'), 'presse')
    for z in c.get('zahlarten') or []:
        merk(z.get('label'), 'zahlarten')
        merk(z.get('note'), 'zahlarten')
    v = c.get('versand') or {}
    merk(v.get('handlingDays'), 'versand')
    for art, doc in (c.get('recht') or {}).items():
        merk((doc or {}).get('title'), 'recht')
        merk((doc or {}).get('updated'), 'recht')
        for s in (doc or {}).get('sections') or []:
            merk(s.get('heading'), 'recht')
            for b in s.get('blocks') or []:
                if 'p' in b:
                    merk(b['p'], 'recht')
                for li in b.get('ul') or []:
                    merk(li, 'recht')
    _QU['wert'] = m
    return m


# ------------------------------------------------------------------ Regeln aus der Schicht
ZAHLWORT = ['Zero', 'One', 'Two', 'Three', 'Four', 'Five', 'Six', 'Seven', 'Eight', 'Nine', 'Ten', 'Eleven', 'Twelve', 'Thirteen', 'Fourteen', 'Fifteen', 'Sixteen',
            'Seventeen', 'Eighteen', 'Nineteen']
ZEHNER = ['', '', 'Twenty', 'Thirty', 'Forty', 'Fifty', 'Sixty', 'Seventy', 'Eighty', 'Ninety']


def zahlwort(n):
    """14 → Fourteen, 30 → Thirty, 45 → Forty-five, 100 → One hundred (für «Fourteen days.» auf Shipping & Payments)."""
    if n < 20:
        return ZAHLWORT[n]
    if n < 100:
        return ZEHNER[n // 10] + ('-' + ZAHLWORT[n % 10].lower() if n % 10 else '')
    rest = n % 100
    return ZAHLWORT[n // 100] + ' hundred' + (' and ' + zahlwort(rest).lower() if rest else '')


def tage(v):
    """Rückgabefrist als ganze Zahl 1–365, sonst None."""
    try:
        f = float(str(v).replace(',', '.'))
    except (TypeError, ValueError):
        return None
    return int(f) if f == int(f) and 1 <= f <= 365 else None


def recht_nummer(h):
    """«1. Who We Are» → '01' (so setzt die Website die Nummer, components/LegalAtelier.tsx split)."""
    m = re.match(r'^(\d+)\.\s+(.*)$', norm(h))
    return m.group(1).zfill(2) if m else ''


def recht_titel(h):
    m = re.match(r'^(\d+)\.\s+(.*)$', norm(h))
    return m.group(2) if m else norm(h)


def versand_regeln(cv, v):
    """Rückgabefrist: die Sätze, wie die Website sie aus SHIPPING.returnDays setzt (app/shipping-payments/page.tsx, lib/i18n.ts shippingText)
    und den Titel «Fourteen days.», der dort als fester Satz steht."""
    alt, neu = tage(cv.get('returnDays')), tage(v.get('returnDays'))
    if not alt or not neu or alt == neu:
        return []
    tg = lambda n: f'{n} day' if n == 1 else f'{n} days'  # noqa: E731
    paare = [
        (f'{zahlwort(alt)} {"day" if alt == 1 else "days"}.', f'{zahlwort(neu)} {"day" if neu == 1 else "days"}.', '/shipping-payments/'),
        (f'{tg(alt)} after delivery', f'{tg(neu)} after delivery', '/shipping-payments/'),
        (f'As a consumer in the EU you can withdraw within {tg(alt)} of receiving your order, unworn and with the label on. txtme.social will confirm the exact process.',
         f'As a consumer in the EU you can withdraw within {tg(neu)} of receiving your order, unworn and with the label on. txtme.social will confirm the exact process.', '/shipping-payments/'),
        (f'Shipped insured, shipping included in the price. Delivery times to follow. Return within {tg(alt)}, unworn, label on.',
         f'Shipped insured, shipping included in the price. Delivery times to follow. Return within {tg(neu)}, unworn, label on.', '*'),
    ]
    return [r for r in (_paar(a, b, sei, 'versand', 'returnDays') for a, b, sei in paare) if r]


def _paar(alt, neu, seite='*', teil='texte', schl=None):
    alt, neu = norm(alt), norm(neu)
    if not alt or alt == neu:
        return None
    return {'art': 'text', 'seite': seite or '*', 'alt': alt, 'neu': neu, 'teil': teil, 'schl': schl}


def regeln(c, cd=None):
    """Die Schicht c (stand oder entwurf) als flache Liste von Regeln."""
    cd = code() if cd is None else cd
    R = []
    # Ausblenden (Le Bureau C): «/seite/|Text» → der Baustein, in dem dieser Text allein steht, bekommt «hidden» (zuerst, damit ein geänderter Text weiter passt)
    for k, v in (c.get('aus') or {}).items():
        if v and '|' in k:
            seite, txt = k.split('|', 1)
            if norm(txt):
                R.append({'art': 'aus', 'seite': seite or '*', 'alt': norm(txt), 'teil': 'aus', 'schl': k})
    for i, t in enumerate(c.get('texte') or []):
        r = _paar(t.get('alt'), t.get('neu'), t.get('seite') or '*', 'texte', ((t.get('seite') or '*'), norm(t.get('alt'))))
        if r:
            R.append(r)
    for src, neu in (c.get('bilder') or {}).items():
        if neu and neu != src:
            R.append({'art': 'bild', 'seite': '*', 'alt': src, 'neu': neu, 'teil': 'bilder', 'schl': src})
    for src, text in (c.get('alt') or {}).items():
        if text:
            R.append({'art': 'alt', 'seite': '*', 'src': src, 'neu': norm(text), 'teil': 'alt', 'schl': src})
    # Angaben: Wert aus dem Code → neuer Wert, auf allen Seiten, dazu mailto:/tel:-Links
    ca, site = cd.get('angaben') or {}, cd.get('site') or {}
    for k, v in (c.get('angaben') or {}).items():
        if k in ('tagline', 'description'):
            alt = site.get(k) or ''
        else:
            alt = ca.get(k) or ''
        if isinstance(v, dict):
            v = v.get('en') or ''
        if isinstance(alt, str) and alt and isinstance(v, str) and v:
            r = _paar(alt, v, '*', 'angaben', k)
            if r:
                R.append(r)
                if 'mail' in k.lower() or '@' in alt:
                    R.append({'art': 'href', 'seite': '*', 'alt': 'mailto:' + alt, 'neu': 'mailto:' + v, 'teil': 'angaben', 'schl': k})
                if k == 'phone':
                    R.append({'art': 'href', 'seite': '*', 'alt': 'tel:' + re.sub(r'[^\d+]', '', alt), 'neu': 'tel:' + re.sub(r'[^\d+]', '', v), 'teil': 'angaben', 'schl': k})
    # Fragen: je id Frage und Antwort, Gruppentitel
    for sp, gruppen in (c.get('fragen') or {}).items():
        if sp != 'en':   # die Website steht auf Englisch; deutsche Fragen meldet Backstage als «nicht auf der Website»
            continue
        alt_g = {g.get('id'): g for g in (cd.get('fragen') or {}).get(sp) or []}
        for g in gruppen or []:
            ag = alt_g.get(g.get('id'))
            if not ag:
                continue
            r = _paar(ag.get('title'), g.get('title'), '*', 'fragen', sp)
            if r:
                R.append(r)
            alt_i = {it.get('id'): it for it in ag.get('items') or []}
            for it in g.get('items') or []:
                ai = alt_i.get(it.get('id'))
                if not ai:
                    continue
                for f in ('q', 'a'):
                    r = _paar(ai.get(f), it.get(f), '*', 'fragen', sp)
                    if r:
                        R.append(r)
    # Presse: Meldungen je id, Material je Stelle
    pr, cpr = c.get('presse') or {}, cd.get('presse') or {}
    for sp, liste in (pr.get('eintraege') or {}).items():
        if sp != 'en':
            continue
        alt_e = {e.get('id'): e for e in (cpr.get('eintraege') or {}).get(sp) or []}
        for e in liste or []:
            ae = alt_e.get(e.get('id'))
            if not ae:
                continue
            for f in ('title', 'summary', 'outlet'):
                r = _paar(ae.get(f), e.get(f), '*', 'presse', sp)
                if r:
                    R.append(r)
    for sp, liste in (pr.get('kit') or {}).items():
        if sp != 'en':
            continue
        alt_k = (cpr.get('kit') or {}).get(sp) or []
        for i, e in enumerate(liste or []):
            if i < len(alt_k):
                r = _paar(alt_k[i].get('label'), e.get('label'), '*', 'presse', sp)
                if r:
                    R.append(r)
                if e.get('href') and e.get('href') != '#' and alt_k[i].get('href') and alt_k[i].get('href') != e.get('href'):
                    R.append({'art': 'href', 'seite': '*', 'alt': alt_k[i]['href'], 'neu': e['href'], 'teil': 'presse', 'schl': sp})
    # Rechtstexte: Titel, Stand, Abschnitte und Blöcke je Stelle
    for art, doc in (c.get('recht') or {}).items():
        ad = (cd.get('recht') or {}).get(art) or {}
        for f in ('title', 'updated'):
            r = _paar(ad.get(f), (doc or {}).get(f), '*', 'recht', art)
            if r:
                R.append(r)
        asec = ad.get('sections') or []
        for i, s in enumerate((doc or {}).get('sections') or []):
            if i >= len(asec):
                continue
            # Die Website setzt «1. Who We Are» als Nummer «01» und Titel «Who We Are» (LegalAtelier split): ersetzt wird der Titel, auf der Seite des Textes
            r = _paar(recht_titel(asec[i].get('heading')), recht_titel(s.get('heading')), '/' + art + '/', 'recht', art)
            if r:
                R.append(r)
            ab = asec[i].get('blocks') or []
            for j, b in enumerate(s.get('blocks') or []):
                if j >= len(ab):
                    continue
                if 'p' in b and 'p' in ab[j]:
                    r = _paar(ab[j]['p'], b['p'], '*', 'recht', art)
                    if r:
                        R.append(r)
                if 'ul' in b and 'ul' in ab[j]:
                    for m, li in enumerate(b['ul']):
                        if m < len(ab[j]['ul']):
                            r = _paar(ab[j]['ul'][m], li, '*', 'recht', art)
                            if r:
                                R.append(r)
    # Zahlarten: Name, Hinweis, Länder je id
    alt_z = {z.get('id'): z for z in cd.get('zahlarten') or []}
    for z in c.get('zahlarten') or []:
        az = alt_z.get(z.get('id'))
        if not az:
            continue
        note = z.get('note')
        note = note.get('en') if isinstance(note, dict) else note
        for alt, neu in ((az.get('label'), z.get('label')), (az.get('note'), note), (az.get('avail'), z.get('avail'))):
            r = _paar(alt, neu, '*', 'zahlarten', z.get('id'))
            if r:
                R.append(r)
    # Versand: nur Texte, die im Code schon stehen (Bearbeitungszeit); Zahlen wie «14» wären auf der Seite nicht eindeutig
    # Versand: die Rückgabefrist steht in vier Sätzen; Bearbeitung, Kosten, Länder zeigt die gebaute Seite nicht (Backstage sagt das)
    v, cv = c.get('versand') or {}, cd.get('versand') or {}
    R.extend(versand_regeln(cv, v))
    return R


# ------------------------------------------------------------------ Anwenden auf eine Seite
def _tok_html(s):
    """Text so, wie er im eingebetteten Datenstrom von React steht: JSON in einer JS-Zeichenkette, < > & als \\u00xx."""
    inner = json.dumps(s, ensure_ascii=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')
    return json.dumps(inner, ensure_ascii=False)[1:-1]


def _tok_txt(s):
    return json.dumps(s, ensure_ascii=False).replace('<', '\\u003c').replace('>', '\\u003e').replace('&', '\\u0026')


def _ersetze_textknoten(t, alt, neu):
    n = [0]
    esc = _h.escape(neu, quote=False)

    def f(m):
        seg = m.group(2)
        if norm(_h.unescape(seg)) == alt:
            n[0] += 1
            v = re.match(r'^(\s*)(.*?)(\s*)$', seg, re.S)
            return m.group(1) + v.group(1) + esc + v.group(3) + m.group(3)
        return m.group(0)
    t = re.sub(r'(>)([^<>]+)(<)', f, t)
    return t, n[0]


_ROLL = re.compile(r'(<span class="sr-only">)([^<]*)(</span>)((?:<span class="bst" aria-hidden="true"><i>[^<]*</i><i class="unten">[^<]*</i></span>|<span aria-hidden="true">(?:&nbsp;|\u00a0| )</span>)+)')


def _roll_angleichen(t):
    """Rolltext der Website (Menüpunkte, Menu/Cart): der lesbare Text steht in «sr-only», sichtbar sind die Buchstaben daneben.
    Wurde der Text geändert, werden die Buchstaben aus dem neuen Text neu gesetzt, genau wie RollText.tsx sie baut."""
    def f(m):
        text = _h.unescape(m.group(2))
        teile = re.findall(r'<span[^>]*>.*?</span>', m.group(4))
        buch = ''.join(_h.unescape(re.search(r'<i>([^<]*)</i>', x).group(1)) if 'class="bst"' in x else ' ' for x in teile)
        if buch == text:
            return m.group(0)
        neu = ''.join('<span aria-hidden="true">\u00a0</span>' if ch == ' ' else '<span class="bst" aria-hidden="true"><i>%s</i><i class="unten">%s</i></span>' % ((_h.escape(ch, quote=False),) * 2) for ch in text)
        return m.group(1) + m.group(2) + m.group(3) + neu
    return _ROLL.sub(f, t)


def ausblenden(t, alt, art='html'):
    """Den Baustein, in dem genau dieser Text allein steht, ausblenden statt löschen: im HTML «hidden=""», im Datenstrom von React «hidden:true»
    (React setzt hidden="" genauso, die Seite hydriert ohne Abweichung, auch beim Wechsel zwischen Seiten über index.txt)."""
    n = [0]
    if art == 'html':
        def f(m):
            if norm(_h.unescape(m.group(3))) != alt or re.search(r'\shidden(=|\s|$)', m.group(2)):
                return m.group(0)
            n[0] += 1
            return '<' + m.group(1) + m.group(2) + ' hidden="">' + m.group(3) + '</' + m.group(1) + '>'
        t = re.sub(r'<([a-z][a-z0-9]*)((?:\s[^<>]*)?)>([^<>]+)</\1>', f, t)
        tok = '\\"children\\":' + _tok_html(alt)
        neu = '\\"hidden\\":true,' + tok
    else:
        tok = '"children":' + _tok_txt(alt)
        neu = '"hidden":true,' + tok
    k = t.count(tok) - t.count(neu)
    if k > 0:
        t = t.replace(neu, '\0BS\0').replace(tok, neu).replace('\0BS\0', neu)
        n[0] += k
    return t, n[0]


_AUSB = {}


def _ausb_seite(k):
    """Je gebauter Seite einmal: wie oft steht jeder Text allein in einem Baustein (HTML), Inhalt (Datei-Stand als Schlüssel)."""
    datei = os.path.join(OUT, k, 'index.html') if k else os.path.join(OUT, 'index.html')
    if not os.path.exists(datei):
        return None
    txt_datei = os.path.join(os.path.dirname(datei), 'index.txt')
    stempel = (os.path.getmtime(datei), os.path.getmtime(txt_datei) if os.path.exists(txt_datei) else 0)
    w = _AUSB.get(k)
    if w and w[0] == stempel:
        return w[1]
    with open(datei, encoding='utf-8') as f:
        html = f.read()
    knoten, sprung = {}, set()
    for m in re.finditer(r'<([a-z][a-z0-9]*)((?:\s[^<>]*)?)>([^<>]+)</\1>', html):
        t = norm(_h.unescape(m.group(3)))
        knoten[t] = knoten.get(t, 0) + 1
        if m.group(1) == 'a' and re.search(r'\shref="#', m.group(2) or ''):   # Sprunglink («Skip to content») für Tastatur und Vorleseprogramme: nie ausblenden
            sprung.add(t)
    txt = None
    if os.path.exists(txt_datei):
        with open(txt_datei, encoding='utf-8') as f:
            txt = f.read()
    w = {'html': html, 'txt': txt, 'knoten': knoten, 'sprung': sprung}
    _AUSB[k] = (stempel, w)
    return w


def ausblendbar(k, alt):
    """Lässt sich der Satz auf der gebauten Seite k sauber ausblenden? Nur wenn er im HTML allein in seinem Baustein steht UND
    im Datenstrom von React (eingebettet und index.txt) als eigener Inhalt dieses Bausteins: sonst zeigte ihn React wieder."""
    w = _ausb_seite(k)
    if not w:
        return False
    n = w['knoten'].get(alt, 0)
    if not n or alt in w.get('sprung', ()):
        return False
    strom = w['html'].count('\\"children\\":' + _tok_html(alt))
    txt = 1 if w['txt'] is None else w['txt'].count('"children":' + _tok_txt(alt))
    return strom >= 1 and txt >= 1 and n == strom


def _ersetze_rohe(t, alt, neu, art):
    """Im Datenstrom (HTML: \\"…\\" / index.txt: "…")."""
    if art == 'txt':
        tok, tn = _tok_txt(alt), _tok_txt(neu)
    else:
        tok, tn = _tok_html(alt), _tok_html(neu)
    n = t.count(tok)
    if n:
        t = t.replace(tok, tn)
    return t, n


def _ersetze_pfad(t, alt, neu):
    pat = re.compile(r'(?<=["\s,(])' + re.escape(alt) + r'(?=["\s,)\\])')
    n = len(pat.findall(t))
    return (pat.sub(neu.replace('\\', '\\\\'), t) if n else t), n


def _seo(t, se):
    titel, beschr = norm(se.get('title') or ''), norm(se.get('description') or '')
    if titel:
        voll = _h.escape(titel + ' — ' + NAME_SITE, quote=True)
        t = re.sub(r'<title>.*?</title>', '<title>' + voll + '</title>', t, count=1, flags=re.S)
        t = re.sub(r'(<meta (?:property="og:title"|name="twitter:title") content=")[^"]*(")', r'\g<1>' + voll.replace('\\', '\\\\') + r'\2', t)
    if beschr:
        b = _h.escape(beschr, quote=True).replace('\\', '\\\\')
        t = re.sub(r'(<meta (?:name="description"|property="og:description"|name="twitter:description") content=")[^"]*(")', r'\g<1>' + b + r'\2', t)
    return t


