def momentaufnahme(text):
    """Die Seite ohne die Skripte des Shops: steht still, nichts hydriert (die Website zeigt ohne JavaScript alle Inhalte, Stand a216c42). Für die Rahmen im Bureau."""
    text = re.sub(r'<script[^>]*src="/_next/[^"]*"[^>]*></script>', '', text)
    text = re.sub(r'<script>(?:self\.)?__next_f[\s\S]*?</script>', '', text)
    text = re.sub(r'<script>\(self\.__next_f[\s\S]*?</script>', '', text)
    text = re.sub(r'<link rel="(?:modulepreload|preload)" [^>]*as="script"[^>]*>', '', text)
    return text


