#!/usr/bin/env python3
"""Die Wache (Master 5.3): eine gemeinsame Sicherheitsschicht, die der Server vor jedem Lesen und Schreiben ruft.

Host und Herkunft (421/403) · Grenze je Absender und Minute (600 lesen / 60 schreiben, 429 mit Retry-After) · Grösse (32 MB, 413)
· Rollen (admin, redaktion, lesen; 403 bei Verstoss) · Anmeldung mit Passwort (Sitzung 12 Stunden, Sperre nach 5 Fehlversuchen)
· Protokoll mit «wer». Solange kein Benutzer angelegt ist (R22: kein Passwort bis zur Auslieferung), läuft alles offen in der Rolle admin;
die Anmeldung kommt davor, ohne dass das Werkzeug umgebaut wird."""
import hashlib
import hmac
import json
import os
import re
import secrets
import threading
import time

LESEN_JE_MIN, SCHREIBEN_JE_MIN, GROESSE_MAX = 600, 60, 32 * 1024 * 1024
SITZUNG_S = 12 * 3600
FEHLVERSUCHE, SPERRE_S = 5, 600
ROLLEN = ('admin', 'redaktion', 'lesen')
# Welche Rolle darf welchen Weg (POST): alles andere (GET) darf jede Rolle. 'alle' = auch ohne Rolle (Fehlermelder, Anmeldung).
RECHTE = {
    'aendern': ('admin', 'redaktion'), 'zuruecknehmen': ('admin', 'redaktion'), 'verwerfen': ('admin', 'redaktion'), 'rueckgaengig': ('admin', 'redaktion'),
    'veroeffentlichen': ('admin', 'redaktion'), 'zurueckholen': ('admin', 'redaktion'), 'bild': ('admin', 'redaktion'), 'bau': ('admin', 'redaktion'),
    'fragen': ('admin', 'redaktion'), 'eingang': ('admin', 'redaktion'), 'antwort': ('admin', 'redaktion'),
    'reparieren': ('admin',), 'zugang': ('alle',), 'fehler': ('alle',),
}


class Abgewiesen(Exception):
    def __init__(self, status, text, lex='anfrage', kopf=None):
        super().__init__(text)
        self.status, self.lex, self.kopf = status, lex, kopf or {}


class Wache:
    def __init__(self, daten, port, protokoll):
        self.daten, self.port, self.protokoll = daten, port, protokoll
        self.f_zugang = os.path.join(daten, 'zugang.json')
        self.f_sitz = os.path.join(daten, 'sitzungen.json')
        self.f_offen = os.path.join(daten, 'offen')
        self.schloss = threading.Lock()
        self.zaehler = {}      # ip → {'lesen': [zeiten], 'schreiben': [zeiten]}
        self.versuche = {}     # ip|name → [zeiten der Fehlversuche]
        self.sitzungen = self._lies(self.f_sitz, {})

    # ---------- Dateien
    def _lies(self, p, sonst):
        try:
            with open(p, encoding='utf-8') as f:
                return json.load(f)
        except (OSError, ValueError):
            return sonst

    def _schreib(self, p, d):
        os.makedirs(os.path.dirname(p), exist_ok=True)
        tmp = p + '.neu'
        with open(tmp, 'w', encoding='utf-8') as f:
            json.dump(d, f, ensure_ascii=False, indent=1)
        os.replace(tmp, p)

    def zugang(self):
        z = self._lies(self.f_zugang, {}) or {}
        z.setdefault('benutzer', [])
        return z

    def offen(self):
        """Ohne Passwort offen: kein Benutzer angelegt, oder die Datei inhalt/offen liegt da (Notausgang, siehe Lexikon «anmeldung»)."""
        return os.path.exists(self.f_offen) or not self.zugang()['benutzer']

    # ---------- Host, Herkunft, Grösse, Grenze
    def host_pruefen(self, host):
        h = (host or '').split(':')[0].strip('[]').lower()
        if h not in ('127.0.0.1', 'localhost', '::1', '0.0.0.0'):
            raise Abgewiesen(421, 'HOST · Falscher Host: Backstage antwortet nur unter 127.0.0.1.', 'host')

    def herkunft_pruefen(self, origin, referer, host):
        """POST nur von der eigenen Seite: fremder oder «null»-Origin → 403 (S01)."""
        eigene = {f'http://{h}:{self.port}' for h in ('127.0.0.1', 'localhost', '[::1]')} | {f'http://{h}' for h in ('127.0.0.1', 'localhost')}
        if host:
            eigene.add('http://' + host)
        o = (origin or '').strip().lower().rstrip('/')
        if o:
            if o == 'null' or o not in eigene:
                raise Abgewiesen(403, 'HERKUNFT · Die Anfrage kommt nicht von Backstage selbst und wurde abgewiesen.', 'herkunft')
            return
        r = (referer or '').strip().lower()
        if r and not any(r.startswith(e + '/') or r == e for e in eigene):
            raise Abgewiesen(403, 'HERKUNFT · Die Anfrage kommt nicht von Backstage selbst und wurde abgewiesen.', 'herkunft')

    def groesse_pruefen(self, laenge):
        if laenge > GROESSE_MAX:
            raise Abgewiesen(413, f'GROESSE · Die Anfrage ist grösser als {GROESSE_MAX // (1024 * 1024)} MB und wurde abgewiesen.', 'datei-gross')

    def grenze(self, ip, schreiben):
        art = 'schreiben' if schreiben else 'lesen'
        max_ = SCHREIBEN_JE_MIN if schreiben else LESEN_JE_MIN
        jetzt = time.time()
        with self.schloss:
            z = self.zaehler.setdefault(ip, {'lesen': [], 'schreiben': []})[art]
            while z and z[0] < jetzt - 60:
                z.pop(0)
            if len(z) >= max_:
                warte = int(60 - (jetzt - z[0])) + 1
                raise Abgewiesen(429, f'ZUVIELE · Zu viele Anfragen in einer Minute ({max_} {art}). In {warte} Sekunden geht es weiter.', 'zuviele', {'Retry-After': str(warte)})
            z.append(jetzt)

    def absender(self, ip, kekse):
        """Wer zählt für die Grenze: der Rechner, und mit gültiger Anmeldung die angemeldete Person (zwei Personen am selben Rechner
        teilen sich die Grenze dann nicht). Ein erfundener Keks zählt nicht als eigene Person."""
        tok = (kekse or {}).get('bs_sitzung')
        s = self.sitzungen.get(tok) if tok else None
        return f"{ip}|{s['name']}" if s and s.get('bis', 0) > time.time() else ip

    def grenze_zuruecksetzen(self):
        with self.schloss:
            self.zaehler.clear()

    # ---------- Rollen und Sitzungen
    def _hash(self, pw, salz):
        return hashlib.pbkdf2_hmac('sha256', pw.encode('utf-8'), bytes.fromhex(salz), 120000).hex()

    def wer(self, kekse):
        """{'name', 'rolle', 'angemeldet'} für diese Anfrage."""
        if self.offen():
            return {'name': 'offen', 'rolle': 'admin', 'angemeldet': True, 'offen': True}
        tok = (kekse or {}).get('bs_sitzung')
        s = self.sitzungen.get(tok) if tok else None
        if s and s.get('bis', 0) > time.time():
            return {'name': s['name'], 'rolle': s['rolle'], 'angemeldet': True, 'offen': False}
        return {'name': '', 'rolle': '', 'angemeldet': False, 'offen': False}

    def darf(self, wer, weg):
        rechte = RECHTE.get(weg, ('admin', 'redaktion'))
        if 'alle' in rechte:
            return
        if not wer['angemeldet']:
            raise Abgewiesen(401, 'ANMELDUNG · Bitte anmelden.', 'anmeldung')
        if wer['rolle'] not in rechte:
            raise Abgewiesen(403, f'ROLLE · Die Rolle «{wer["rolle"]}» darf das nicht ({weg}). Nötig: {" oder ".join(rechte)}.', 'rolle')

    def _gesperrt(self, k):
        jetzt = time.time()
        v = [t for t in self.versuche.get(k, []) if t > jetzt - SPERRE_S]
        self.versuche[k] = v
        return len(v) >= FEHLVERSUCHE

    def anmelden(self, name, pw, ip):
        z = self.zugang()
        name = (name or '').strip()
        if not z['benutzer']:
            raise Abgewiesen(400, 'ZUGANG · Es ist noch kein Benutzer angelegt; Backstage ist ohne Passwort offen.', 'zugang')
        if not name and len(z['benutzer']) == 1:
            name = z['benutzer'][0]['name']
        k = ip + '|' + name.lower()
        if self._gesperrt(k):
            raise Abgewiesen(429, 'GESPERRT · Zu viele Fehlversuche, zehn Minuten warten.', 'gesperrt')
        b = next((x for x in z['benutzer'] if x['name'].lower() == name.lower()), None)
        if not b or not hmac.compare_digest(self._hash(pw or '', b['salz']), b['hash']):
            self.versuche.setdefault(k, []).append(time.time())
            raise Abgewiesen(401, 'ANMELDUNG · Name oder Passwort stimmen nicht.', 'anmeldung')
        tok = secrets.token_urlsafe(32)
        with self.schloss:
            self.sitzungen = {t: s for t, s in self.sitzungen.items() if s.get('bis', 0) > time.time()}
            self.sitzungen[tok] = {'name': b['name'], 'rolle': b['rolle'], 'bis': time.time() + SITZUNG_S}
            self._schreib(self.f_sitz, self.sitzungen)
        self.protokoll(b['name'], b['rolle'], 'angemeldet')
        return tok, b

    def abmelden(self, tok):
        with self.schloss:
            s = self.sitzungen.pop(tok, None)
            self._schreib(self.f_sitz, self.sitzungen)
        if s:
            self.protokoll(s['name'], s['rolle'], 'abgemeldet')

    def benutzer_pruefen(self, name, pw, rolle):
        name = re.sub(r'\s+', ' ', str(name or '')).strip()
        if not re.fullmatch(r'[\w .\-@]{2,40}', name):
            raise Abgewiesen(400, 'EINGABE · Der Name braucht 2 bis 40 Zeichen (Buchstaben, Zahlen, Punkt, Bindestrich).', 'pflichtfeld')
        if len(pw or '') < 8:
            raise Abgewiesen(400, 'PASSWORT · Das Passwort braucht mindestens 8 Zeichen.', 'passwort-kurz')
        if rolle not in ROLLEN:
            raise Abgewiesen(400, 'EINGABE · Rolle muss admin, redaktion oder lesen sein.', 'rolle')
        return name

    def benutzer_neu(self, name, pw, rolle, von):
        name = self.benutzer_pruefen(name, pw, rolle)
        z = self.zugang()
        if any(b['name'].lower() == name.lower() for b in z['benutzer']):
            raise Abgewiesen(400, 'DOPPELT · Diesen Namen gibt es schon.', 'doppelt')
        salz = secrets.token_hex(16)
        z['benutzer'].append({'name': name, 'rolle': rolle, 'salz': salz, 'hash': self._hash(pw, salz), 'seit': time.strftime('%Y-%m-%dT%H:%M:%S')})
        self._schreib(self.f_zugang, z)
        if os.path.exists(self.f_offen):
            os.remove(self.f_offen)
        self.protokoll(von['name'], von['rolle'], f'Benutzer angelegt: {name} ({rolle})')
        return z

    def benutzer_weg(self, name, von):
        z = self.zugang()
        rest = [b for b in z['benutzer'] if b['name'].lower() != str(name or '').lower()]
        if len(rest) == len(z['benutzer']):
            raise Abgewiesen(400, 'VERALTET · Diesen Benutzer gibt es nicht.', 'veraltet')
        if rest and not any(b['rolle'] == 'admin' for b in rest):
            raise Abgewiesen(400, 'ROLLE · Der letzte Admin kann nicht gelöscht werden.', 'rolle')
        z['benutzer'] = rest
        self._schreib(self.f_zugang, z)
        with self.schloss:
            self.sitzungen = {t: s for t, s in self.sitzungen.items() if s['name'].lower() != str(name).lower()}
            self._schreib(self.f_sitz, self.sitzungen)
        self.protokoll(von['name'], von['rolle'], f'Benutzer gelöscht: {name}')
        return z

    def passwort(self, name, pw, von):
        if len(pw or '') < 8:
            raise Abgewiesen(400, 'PASSWORT · Das Passwort braucht mindestens 8 Zeichen.', 'passwort-kurz')
        z = self.zugang()
        b = next((x for x in z['benutzer'] if x['name'].lower() == str(name or '').lower()), None)
        if not b:
            raise Abgewiesen(400, 'VERALTET · Diesen Benutzer gibt es nicht.', 'veraltet')
        b['salz'] = secrets.token_hex(16)
        b['hash'] = self._hash(pw, b['salz'])
        self._schreib(self.f_zugang, z)
        self.protokoll(von['name'], von['rolle'], f'Passwort neu: {b["name"]}')

    def oeffnen(self, von):
        """Alle Benutzer weg: Backstage wieder ohne Passwort offen (nur admin)."""
        self._schreib(self.f_zugang, {'benutzer': []})
        with self.schloss:
            self.sitzungen = {}
            self._schreib(self.f_sitz, self.sitzungen)
        self.protokoll(von['name'], von['rolle'], 'Passwortschutz aufgehoben: Backstage offen')

    def stand(self, wer):
        z = self.zugang()
        return {'offen': self.offen(), 'eingerichtet': bool(z['benutzer']), 'angemeldet': wer['angemeldet'], 'name': wer['name'], 'rolle': wer['rolle'],
                'benutzer': [{'name': b['name'], 'rolle': b['rolle'], 'seit': b.get('seit', '')} for b in z['benutzer']], 'rollen': list(ROLLEN),
                'notausgang': os.path.exists(self.f_offen)}

